// correspondence.mjs — which peak is which compound.
//
// Kept strictly separate from visual alignment. A CONFIRMED assignment is a
// user statement. A PROPOSED assignment is produced by a stated method with a
// stated basis and uncertainty, and is never used in a calculation until the
// user accepts it. Peak position, equal peak counts and monotonic retention
// behaviour are never treated as proof of identity.
import { newId } from '../data-model/ids.mjs';
import { TEACHING_COMPOUNDS } from '../presets/bps2032.mjs';
import { peakExcluded } from '../data-model/peak-filter.mjs';

export const PREDICTION_WINDOW = { minMinutes: 0.05, fraction: 0.03,
  note: 'Tool default: a peak is a candidate for a predicted compound when it lies within max(0.05 min, 3 % of the predicted tR). Editable in code; not a course rule.' };

// One compound per name. Two records with the same name would split that
// compound's points between two lines and leave peaks unattributed, so an
// existing record is returned instead of a duplicate being created. The role
// is upgraded to "marker" if the new statement says so; it is never downgraded
// silently.
export function addCompound(session, name, role = 'analyte', idGen) {
  const clean = String(name).trim();
  const key = clean.toLowerCase();
  const existing = session.compounds.find(c => c.name.toLowerCase() === key);
  if (existing) {
    if (role === 'marker' && existing.role !== 'marker') existing.role = 'marker';
    existing.duplicateRequested = true;
    return existing;
  }
  const c = { id: newId('cmp', idGen), name: clean, role };
  session.compounds.push(c); return c;
}
export function loadTeachingCompounds(session, idGen) {
  const out = [];
  for (const t of TEACHING_COMPOUNDS) if (!session.compounds.some(c => c.name === t.name)) out.push(addCompound(session, t.name, t.role, idGen));
  return out;
}

export function assign(session, runId, peakNo, compoundId, { basis = 'user assignment', idGen } = {}) {
  // a compound occupies at most one peak per run; replace any earlier confirmation
  session.assignments = session.assignments.filter(a => !(a.runId === runId && a.compoundId === compoundId));
  const a = { id: newId('asg', idGen), runId, peakNo, compoundId, state: 'confirmed', ambiguous: false, basis, by: 'user' };
  session.assignments.push(a); return a;
}
export function unassign(session, runId, peakNo, compoundId) {
  const before = session.assignments.length;
  session.assignments = session.assignments.filter(a => !(a.runId === runId && a.peakNo === peakNo && (compoundId == null || a.compoundId === compoundId)));
  return before - session.assignments.length;
}
export function acceptProposal(session, assignmentId) {
  const p = session.assignments.find(a => a.id === assignmentId);
  if (!p || p.state !== 'proposed') return null;
  return assign(session, p.runId, p.peakNo, p.compoundId, { basis: `${p.basis} — accepted by user` });
}
export function clearProposals(session, runId = null) {
  session.assignments = session.assignments.filter(a => a.state !== 'proposed' || (runId && a.runId !== runId));
}

export function peakStatus(session, run) {
  const asg = session.assignments.filter(a => a.runId === run.id);
  return run.measured.peaks.map(p => {
    const confirmed = asg.filter(a => a.peakNo === p.no && a.state === 'confirmed').map(a => a.compoundId);
    const proposed = asg.filter(a => a.peakNo === p.no && a.state === 'proposed');
    const note = run.peakNotes?.[p.no] || {};
    let state = 'unmatched';
    if (peakExcluded(run,p)) state = 'excluded';
    else if (confirmed.length >= 2 || note.coeluted) state = 'coeluted';
    else if (confirmed.length === 1) state = 'matched';
    else if (proposed.length > 1 || proposed.some(x => x.ambiguous)) state = 'ambiguous';
    else if (proposed.length === 1) state = 'proposed';
    return { no: p.no, tR: p.tR, state, confirmed, proposed, note };
  });
}

export function missingCompounds(session, run) {
  const have = new Set(session.assignments.filter(a => a.runId === run.id && a.state === 'confirmed').map(a => a.compoundId));
  return session.compounds.filter(c => !have.has(c.id));
}

export function confirmedPeakOf(session, run, compoundId) {
  const a = session.assignments.filter(x => x.runId === run.id && x.compoundId === compoundId && x.state === 'confirmed');
  if (a.length !== 1) return null;
  return run.measured.peaks.find(p => p.no === a[0].peakNo) || null;
}

// Elution-order changes among confirmed compounds across a set of runs.
export function orderChanges(session, runs) {
  const changes = [];
  const ids = session.compounds.map(c => c.id);
  for (let i = 0; i < ids.length; i++) for (let j = i + 1; j < ids.length; j++) {
    const orders = [];
    for (const r of runs) {
      const a = confirmedPeakOf(session, r, ids[i]), b = confirmedPeakOf(session, r, ids[j]);
      if (a && b && a.no !== b.no) orders.push({ runId: r.id, label: r.label, first: a.tR < b.tR ? ids[i] : ids[j] });
    }
    if (new Set(orders.map(o => o.first)).size > 1) changes.push({ a: ids[i], b: ids[j], runs: orders });
  }
  return changes;
}

// Proposals from labels written in the imported file (generic compound_label,
// or a LabSolutions compound-table name). Matching is by exact name or by the
// abbreviation in parentheses, case-insensitive.
export function proposeFromFileLabels(session, run, idGen) {
  const out = [];
  for (const p of run.measured.peaks) {
    const lab = (p.fileName || '').trim().toLowerCase();
    if (!lab) continue;
    const hits = session.compounds.filter(c => { const n = c.name.toLowerCase(); const ab = (/\(([^)]+)\)/.exec(n) || [])[1]; return n === lab || ab === lab; });
    if (hits.length === 1 && !session.assignments.some(a => a.runId === run.id && a.compoundId === hits[0].id)) {
      const a = { id: newId('asg', idGen), runId: run.id, peakNo: p.no, compoundId: hits[0].id, state: 'proposed', ambiguous: false,
        basis: `label "${p.fileName}" written in the imported file`, uncertainty: 'The label is the file author\'s statement; confirm it.', by: 'auto' };
      session.assignments.push(a); out.push(a);
    }
  }
  return out;
}

// Order-based proposal from a reference run with CONFIRMED assignments.
// Offered only when the two runs report the same number of peaks, and even
// then marked low-confidence: equal counts do not establish identities, and a
// missing peak, a co-elution or an order change breaks positional matching.
export function proposeByOrder(session, run, refRun, idGen) {
  const ref = peakStatus(session, refRun).filter(s => s.state === 'matched');
  if (!ref.length) return { ok: false, reason: `Reference run "${refRun.label}" has no confirmed assignments.` };
  if (run.measured.peaks.length !== refRun.measured.peaks.length)
    return { ok: false, reason: `Peak counts differ (${run.measured.peaks.length} vs ${refRun.measured.peaks.length}); positional matching would be ambiguous, so no order-based proposal is made.` };
  const made = [];
  for (const s of ref) {
    const idx = refRun.measured.peaks.findIndex(p => p.no === s.no);
    const target = run.measured.peaks[idx];
    const compoundId = s.confirmed[0];
    if (session.assignments.some(a => a.runId === run.id && a.compoundId === compoundId)) continue;
    const a = { id: newId('asg', idGen), runId: run.id, peakNo: target.no, compoundId, state: 'proposed', ambiguous: false,
      basis: `same elution position as in "${refRun.label}"`, uncertainty: 'LOW: position only. Equal peak counts do not establish identity; elution order can change with solvent, temperature or ligand.', by: 'auto' };
    session.assignments.push(a); made.push(a);
  }
  return { ok: true, made };
}

// Prediction-based proposal: predictions = [{compoundId, tR, basis}].
export function proposeByPrediction(session, run, predictions, idGen) {
  const made = [], notes = [];
  const taken = new Map();
  for (const pr of predictions) {
    if (session.assignments.some(a => a.runId === run.id && a.compoundId === pr.compoundId && a.state === 'confirmed')) continue;
    const w = Math.max(PREDICTION_WINDOW.minMinutes, PREDICTION_WINDOW.fraction * pr.tR);
    const cands = run.measured.peaks.filter(p => Math.abs(p.tR - pr.tR) <= w);
    if (!cands.length) { notes.push({ compoundId: pr.compoundId, text: `no peak within ±${w.toFixed(3)} min of the predicted ${pr.tR.toFixed(3)} min (missing, co-eluted or moved)` }); continue; }
    const best = cands.reduce((m, p) => Math.abs(p.tR - pr.tR) < Math.abs(m.tR - pr.tR) ? p : m);
    const a = { id: newId('asg', idGen), runId: run.id, peakNo: best.no, compoundId: pr.compoundId, state: 'proposed', ambiguous: cands.length > 1,
      basis: `nearest peak to the model-predicted tR ${pr.tR.toFixed(3)} min (${pr.basis})`,
      uncertainty: cands.length > 1 ? `AMBIGUOUS: ${cands.length} peaks lie within ±${w.toFixed(3)} min.` : `One peak within ±${w.toFixed(3)} min; a prediction is not an identification.`, by: 'auto' };
    if (taken.has(best.no)) { a.ambiguous = true; a.uncertainty = 'AMBIGUOUS: the same peak is the nearest match for more than one compound (possible co-elution).'; taken.get(best.no).ambiguous = true; }
    taken.set(best.no, a);
    session.assignments.push(a); made.push(a);
  }
  return { made, notes };
}

// visual.mjs — DISPLAY-ONLY alignment of chromatograms.
//
// These transforms change only the x coordinate used to draw a trace. They
// never change a stored retention time and are never used in a calculation.
// Every aligned view is labelled as aligned.
import { confirmedPeakOf } from './correspondence.mjs';
import { t0Of } from '../data-model/derive.mjs';

export const ALIGN_MODES = {
  original: { label: 'Original retention-time axis (min)', axis: 'tR (min) — as measured' },
  compound: { label: 'Aligned to a selected reference compound (time shift)', axis: 'ALIGNED: tR − tR(reference compound) (min) — not a measured retention time' },
  normalised: { label: 'Normalised retention coordinate K = (t − t0)/t0', axis: 'ALIGNED: (t − t0)/t0 — dimensionless, needs an established t0' },
};

// Returns {ok, map:(t)=>x, note}. When a run lacks what the mode needs it is
// NOT drawn in the aligned view and the reason is reported, so unlike axes are
// never mixed in one plot.
export function alignmentFor(session, run, mode, { compoundId = null, settings } = {}) {
  if (mode === 'original') return { ok: true, map: t => t, note: '' };
  if (mode === 'compound') {
    if (!compoundId) return { ok: false, note: 'Select the reference compound.' };
    const pk = confirmedPeakOf(session, run, compoundId);
    if (!pk) return { ok: false, note: 'The reference compound is not confirmed in this run; the run is not drawn in the aligned view.' };
    return { ok: true, map: t => t - pk.tR, note: `shifted by −${pk.tR.toFixed(3)} min (display only)` };
  }
  if (mode === 'normalised') {
    const t0 = t0Of(session, run, settings);
    if (!t0.ok) return { ok: false, note: `No t0 (${t0.text}); the run is not drawn in the normalised view.` };
    return { ok: true, map: t => (t - t0.t0) / t0.t0, note: `t0 = ${t0.t0.toFixed(3)} min (${t0.method}${t0.proxy ? ', UNCONFIRMED PROXY' : ''})` };
  }
  return { ok: false, note: `Unknown alignment mode ${mode}.` };
}

// auto.mjs — what the tool does for the user without being asked.
//
// The rule that governs everything here: the tool may act on what a FILE
// STATES, and it may act on structure (which runs are comparable with which).
// It may not act on inference about identity. A compound label written in the
// imported file is the file author's statement and is recorded as such, with
// "as stated in the file" as its provenance; a peak order, a monotonic
// retention sequence or a file name is NOT a statement of identity and never
// becomes one here.
//
// Every action is returned in a report, so nothing happens silently.
import { addCompound } from '../alignment/correspondence.mjs';
import { newInstrument, newColumnModel, newPhysicalColumn } from '../data-model/equipment.mjs';
import { organicOf, percentBOf, modeOf, effectiveTemperature, isBlank, runColumn } from '../data-model/derive.mjs';
import { usable, knownValue } from '../data-model/conditions.mjs';
import { newId } from '../data-model/ids.mjs';
import { sampleIdentity, sampleGroupKey } from '../data-model/comparability.mjs';
import { fileInstrumentName, resolveFileInstrument, INSTRUMENT_SUGGESTION } from '../data-model/instrument-association.mjs';

const label = run => run.label || run.id;

// ---------------------------------------------------------------- equipment
// A generic CSV may state the column and the instrument in its own columns, and
// a LabSolutions export states the instrument name. Those are file statements,
// so a record may be created and associated from them. Nothing is read from a
// file NAME, and the created column record carries no geometry and no limits:
// those are datasheet facts the file does not state, so they stay unknown and
// every proposal that needs them reports them as unverified.
export function autoEquipment(session, idGen) {
  const acts = [];
  const assoc = { instrument: new Map(), column: new Map() };
  for (const run of session.runs) {
    const insName = fileInstrumentName(run);
    const prior = run.assoc.instrumentId;
    // Reconcile only our old importer suggestion, never a user override.
    const oldSuggestion = prior.source === INSTRUMENT_SUGGESTION && prior.confirmed === false;
    if (insName && (!prior.value || oldSuggestion)) {
      const resolved = resolveFileInstrument(session, run);
      if (resolved.matches.length > 1) {
        acts.push(`Instrument name "${insName}" matches ${resolved.matches.length} equipment records. No record was selected or confirmed; choose the actual instrument in Equipment.`);
      } else {
        let ins = resolved.record;
        if (!ins && !prior.value) { ins = newInstrument({ label: insName, identifier: insName, provenance: { source: 'file' } }, idGen); session.instruments.push(ins); acts.push(`Created instrument record "${insName}" because the file states that instrument name. No operating limit is recorded for it: a file does not state hardware ratings.`); }
        const association = resolveFileInstrument(session, run).association;
        // Do not redirect an existing suggestion if its target has since changed.
        if (ins && (!prior.value || prior.value === ins.id)) {
          run.assoc.instrumentId = association;
          if (association.confirmed) {
            if (!prior.confirmed) assoc.instrument.set(ins.label, (assoc.instrument.get(ins.label) || 0) + 1);
          } else acts.push(`Instrument name "${insName}" matches an existing equipment record by name only. The association remains unconfirmed; confirm the actual instrument before using its hardware ratings.`);
        }
      }
    }
    const colName = run.measured.fileMeta?.columnLabel || null;
    if (colName && !run.assoc.columnId.value) {
      let col = session.columns.find(c => c.label === colName);
      if (!col) {
        const model = newColumnModel({ product: colName, provenance: { source: 'file' }, notes: 'Created from the column label stated in the imported file. Geometry and datasheet limits are NOT stated by a data file and remain unknown.' }, idGen);
        session.columnModels.push(model);
        col = newPhysicalColumn({ label: colName, modelId: model.id }, idGen); session.columns.push(col);
        acts.push(`Created a column record "${colName}" from the column label stated in the file. Its ligand, geometry and limits are unknown: a data file does not state them, so any proposal that depends on them will say so.`);
      }
      run.assoc.columnId = { value: col.id, source: 'file: column label stated in the file', confirmed: true };
      assoc.column.set(col.label, (assoc.column.get(col.label) || 0) + 1);
    }
  }
  for (const [lab, n] of assoc.instrument) acts.push(`Associated ${n} run(s) with instrument "${lab}", as stated in each run's own file.`);
  for (const [lab, n] of assoc.column) acts.push(`Associated ${n} run(s) with column "${lab}", as stated in each run's own file.`);
  return acts;
}

// ---------------------------------------------------------------- compounds
// A file-stated compound label and a file-stated marker flag are data. They are
// recorded with "as stated in the file" as the basis and are visibly distinct
// from a user confirmation; an identity is never derived from peak order.
export function autoCompoundsFromFile(session, settings, idGen) {
  const acts = [];
  if (settings.useFileLabels === false) return ['File-stated compound labels are switched off in Settings; no identity was recorded.'];
  const recorded = new Map(), markers = [], conflicts = [];
  for (const run of session.runs) {
    // A file can state its own labels inconsistently. Two peaks flagged as the
    // hold-up marker, or one label on two peaks, is a CONFLICT in the file:
    // the tool reports it and records nothing from it, because picking one of
    // the two would be the tool deciding an identity.
    const flagged = run.measured.peaks.filter(p => p.markerFlag === true);
    if (flagged.length > 1) {
      conflicts.push(`${label(run)}: ${flagged.length} peaks (${flagged.map(p => p.no).join(', ')}) are flagged as the hold-up marker in the file. A run has one hold-up time, so no marker was taken from it and t0 is not established for that run — correct the file or choose the marker peak yourself.`);
    }
    const byName = new Map();
    for (const p of run.measured.peaks) { const n = (p.fileName || '').trim().toLowerCase(); if (n) byName.set(n, [...(byName.get(n) || []), p.no]); }
    const dupNames = [...byName.entries()].filter(([, nos]) => nos.length > 1);
    for (const [n, nos] of dupNames) conflicts.push(`${label(run)}: the label "${n}" is on ${nos.length} peaks (${nos.join(', ')}). One compound cannot be two peaks of one run, so nothing was recorded for that label here — it is either a co-elution, a mislabelled peak or two compounds sharing a name.`);
    const blocked = new Set(dupNames.map(([n]) => n));
    const markerBlocked = flagged.length > 1;
    for (const p of run.measured.peaks) {
      const name = (p.fileName || '').trim();
      const isMarker = p.markerFlag === true && !markerBlocked;
      if (!name || blocked.has(name.toLowerCase())) continue;
      let c = session.compounds.find(x => x.name.toLowerCase() === name.toLowerCase() || (/\(([^)]+)\)/.exec(x.name.toLowerCase()) || [])[1] === name.toLowerCase());
      if (!c) { c = addCompound(session, name, isMarker ? 'marker' : 'analyte', idGen); acts.push(`Defined ${isMarker ? 'the hold-up marker' : 'the compound'} "${name}" because the imported file names it.`); }
      if (!session.assignments.some(a => a.runId === run.id && a.peakNo === p.no && a.compoundId === c.id)) {
        session.assignments.push({ id: newId('asg', idGen), runId: run.id, peakNo: p.no, compoundId: c.id, state: 'confirmed', ambiguous: false,
          basis: `compound label "${name}" stated in the imported file`, uncertainty: 'This is the file author\'s statement, recorded as file data. It is not a confirmation by this tool and not a chemical identification.', by: 'file' });
        recorded.set(name, (recorded.get(name) || 0) + 1);
      }
      if (isMarker && run.marker.method === 'none') {
        run.marker = { method: 'peak', peakNo: p.no, t0: null, note: `Marked as the hold-up marker by the "is_marker" column of the imported file.`, confirmed: true };
        markers.push(label(run));
      }
    }
  }
  for (const [name, n] of recorded) acts.push(`Recorded "${name}" in ${n} run(s), each as stated in that run's own file. This is file data, not a confirmation by the tool and not a chemical identification.`);
  if (markers.length) acts.push(`Took the file-flagged hold-up marker in ${markers.length} run(s), giving t0 for each of them from its own marker peak.`);
  for (const c of conflicts) acts.push(`CONFLICT IN THE FILE — ${c}`);
  return acts;
}

// ---------------------------------------------------------------- fit groups
// Compatible groups are structural, not a guess: same confirmed physical
// column, same organic solvent, isocratic, known temperatures within the
// configured tolerance, same pH / additive / phase A where recorded. The
// largest group with at least the configured minimum number of DISTINCT
// compositions is proposed for the retention fit.
export function fitGroups(session, settings) {
  const groups = new Map();
  for (const run of session.runs) {
    if (isBlank(run) || !run.measured.peaks.length) continue;
    const col = runColumn(session, run);
    const T = effectiveTemperature(run, settings);
    const B = percentBOf(run), org = organicOf(run), mode = modeOf(run);
    const why = [];
    if (!col.confirmed || !col.column) why.push('no confirmed physical column');
    if (!org) why.push('no recorded organic solvent');
    if (B === null) why.push('no confirmed %B');
    if (mode && mode !== 'ISO') why.push(`mode is ${mode}, and the log K vs %B model is isocratic`);
    if (!T.known) why.push(`column temperature unknown (${T.reason})`);
    if (why.length) { groups.set(`excluded:${run.id}`, { key: null, excluded: true, runs: [run], reasons: why }); continue; }
    const identity = sampleIdentity(run);
    const sample = sampleGroupKey(session, run);
    if (sample === null) why.push(identity.reason);
    if (why.length) { groups.set(`excluded:${run.id}`, { key: null, excluded: true, runs: [run], reasons: why }); continue; }
    // The explicit ID/equivalence is part of the key; sample TYPE never is.
    // A matching column, solvent and temperature says nothing about identity.
    const bucket = [col.column.id, sample, org, mode || 'ISO', Math.round(T.value / Math.max(settings.tempMatchTolerance || 1, 0.001)),
      knownValue(run.conditions.pH) ? run.conditions.pH.value : '', knownValue(run.conditions.additiveName) ? run.conditions.additiveName.value : '',
      knownValue(run.conditions.additiveConc) ? run.conditions.additiveConc.value : '', knownValue(run.conditions.phaseA) ? run.conditions.phaseA.value : '', knownValue(run.conditions.phaseB)?run.conditions.phaseB.value:'', knownValue(run.conditions.mixAcnPct)?run.conditions.mixAcnPct.value:''].join('|');
    const g = groups.get(bucket) || { key: bucket, excluded: false, runs: [], column: col.column.label, sample, organic: org, temperature: T.value, compositions: new Set() };
    g.runs.push(run); g.compositions.add(B); groups.set(bucket, g);
  }
  const usable_ = [...groups.values()].filter(g => !g.excluded).map(g => ({ ...g, compositions: [...g.compositions].sort((a, b) => a - b) }));
  usable_.sort((a, b) => b.compositions.length - a.compositions.length || b.runs.length - a.runs.length);
  return { groups: usable_, excluded: [...groups.values()].filter(g => g.excluded).map(g => ({ run: g.runs[0], reasons: g.reasons })) };
}

export function autoFitSelection(session, settings) {
  const acts = [];
  const { groups, excluded } = fitGroups(session, settings);
  const eligible = groups.filter(g => g.compositions.length >= (settings.minFitPoints || 3));
  const pool = eligible.length ? eligible : groups;
  const best = pool[0] || null;
  for (const run of session.runs) { run.flags.history = !isBlank(run) && run.measured.peaks.length > 0; }
  if (!best) {
    acts.push('No group of comparable runs could be formed, so no retention fit was proposed.');
    for (const e of excluded) acts.push(`${label(e.run)} cannot join a fit group: ${e.reasons.join('; ')}.`);
    return { acts, group: null, groups, excluded, ambiguous: false };
  }
  // Several groups can be equally good. Choosing one of them by the order the
  // files happened to be imported would be an arbitrary scientific decision
  // dressed as a result, so the tie is reported and NOTHING is ticked.
  const tied = pool.filter(g => g.compositions.length === best.compositions.length && g.runs.length === best.runs.length);
  if (tied.length > 1) {
    for (const run of session.runs) run.flags.fit = false;
    acts.push(`${tied.length} groups of comparable runs are equally plausible for the retention fit — each has ${best.runs.length} run(s) at ${best.compositions.length} distinct composition(s): ${tied.map(g => `sample ${g.sample} on "${g.column}" in ${g.organic} at ${g.temperature.toFixed(1)} °C (${g.compositions.join(', ')} %B)`).join('; ')}. None was selected: choosing between them is a scientific decision, and the order the files were imported in is not a reason. Tick the group you intend to fit in the run table.`);
    for (const e of excluded) acts.push(`${label(e.run)} is not in any fit group: ${e.reasons.join('; ')}.`);
    return { acts, group: null, groups, excluded, ambiguous: true, tied };
  }
  for (const run of session.runs) run.flags.fit = best.runs.includes(run);
  acts.push(`Proposed a retention fit over ${best.runs.length} comparable run(s) at ${best.compositions.length} distinct composition(s) (${best.compositions.join(', ')} %B) for sample ${best.sample} on column "${best.column}" in ${best.organic} at ${best.temperature.toFixed(1)} °C. The group is structural: same sample, column, solvent, mode and temperature within ${settings.tempMatchTolerance} °C.`);
  if (groups.length > 1) acts.push(`${groups.length - 1} other comparable group(s) exist (${groups.filter(g => g !== best).map(g => `${g.runs.length} run(s), sample ${g.sample}, on "${g.column}" in ${g.organic} at ${g.temperature.toFixed(1)} °C`).join('; ')}). The group above was chosen because it has the most distinct compositions; tick a different group in the run table to fit that one instead.`);
  for (const e of excluded) acts.push(`${label(e.run)} is not in any fit group: ${e.reasons.join('; ')}.`);
  return { acts, group: best, groups, excluded };
}

// ---------------------------------------------------------------- one call
// Run after an import. Returns a report of every action, with its basis.
export function autoPrepare(session, settings = session.settings, { idGen } = {}) {
  const report = { equipment: [], compounds: [], fit: [], at: new Date().toISOString(), off: settings.automatic === false };
  if (report.off) { report.note = 'Automatic preparation is switched off in Settings. Nothing was changed.'; return report; }
  report.equipment = autoEquipment(session, idGen);
  report.compounds = autoCompoundsFromFile(session, settings, idGen);
  const f = autoFitSelection(session, settings);
  report.fit = f.acts; report.group = f.group ? { runs: f.group.runs.map(r => r.id), compositions: f.group.compositions, sample: f.group.sample } : null;
  report.ambiguousGroups = f.ambiguous ? f.tied.map(g => ({ sample: g.sample, column: g.column, organic: g.organic, temperature: g.temperature, compositions: g.compositions, runs: g.runs.map(r => r.id) })) : null;
  report.note = 'Everything above follows from what the files state and from which runs are comparable with which. No identity was inferred from peak order, from a retention sequence or from a file name.';
  return report;
}

// Sample comparability is an explicit declaration, never a filename, run
// label, sample type or peak-order inference. The file/user states an ID; the
// tool checks that declaration, not whether the chemistry really is identical.
import { cond, usable, sourceLabel } from './conditions.mjs';
import { newId } from './ids.mjs';

const clean = v => typeof v === 'string' ? v.trim() : '';
export function sampleIdentity(run) {
  const field = run?.conditions?.sampleId;
  const value = clean(field?.value);
  const allowedSource = ['file', 'mapping', 'user'].includes(field?.source);
  const basis = clean(field?.note);
  const known = !!value && usable(field) && allowedSource && (field.source !== 'user' || !!basis);
  return { known, value: known ? value : null, stated: value || null,
    source: field?.source || null, basis,
    reason: !value ? 'sample/study identity is not recorded; sample type, sample name and filenames do not establish identity'
      : !field.confirmed ? 'sample/study identity has not been confirmed as a file or user declaration'
      : !allowedSource ? 'sample/study identity needs an explicit file statement or user declaration, not an inferred profile/assumption'
      : field.source === 'user' && !basis ? 'the user-declared sample/study identity needs its basis recorded'
      : `sample/study ID "${value}" (${sourceLabel(field)}${basis ? `; ${basis}` : ''}); this is a declaration, not chemical identification by the tool` };
}

export function setSampleIdentity(run, value, basis) {
  const id = clean(value), note = clean(basis);
  if (id && !note) throw new Error('State the basis for this sample/study identity declaration.');
  run.conditions.sampleId = cond(id || null, id ? 'user' : null,
    { confirmed: !!id, note: id ? note : '' });
  return run.conditions.sampleId;
}

export function validSampleEquivalence(record) {
  return !!record && !!clean(record.id) && !!clean(record.left) && !!clean(record.right)
    && clean(record.left) === record.left && clean(record.right) === record.right
    && record.left !== record.right && record.by === 'user' && !!clean(record.basis)
    && typeof record.declaredAt === 'string' && Number.isFinite(Date.parse(record.declaredAt));
}

// Explicit equivalence is transitive; each connecting declaration is retained
// as provenance. Invalid or malformed records never confer comparability.
function pathBetween(session, from, to) {
  const queue = [{ id: from, records: [] }], seen = new Set([from]);
  const records = (session.sampleEquivalences || []).filter(validSampleEquivalence);
  while (queue.length) {
    const entry = queue.shift();
    if (entry.id === to) return entry.records;
    for (const record of records) {
      const id = record.left === entry.id ? record.right : record.right === entry.id ? record.left : null;
      if (!id || seen.has(id)) continue;
      seen.add(id); queue.push({ id, records: [...entry.records, record] });
    }
  }
  return null;
}

export function sampleCompare(session, run, reference) {
  const a = sampleIdentity(run), b = sampleIdentity(reference);
  const reasons = [], notes = [];
  if (!a.known) reasons.push(`run "${run?.label || run?.id || 'run'}": ${a.reason}`);
  if (reference !== run && !b.known) reasons.push(`reference "${reference?.label || reference?.id || 'run'}": ${b.reason}`);
  if (reasons.length) return { comparable: false, reasons, notes, identities: [a, b], equivalences: [] };
  const records = a.value === b.value ? [] : pathBetween(session, a.value, b.value);
  if (records === null) reasons.push(`different declared sample/study identities ("${a.value}" vs "${b.value}"); no explicit user equivalence is recorded`);
  else {
    notes.push(a.value === b.value ? `Same declared sample/study ID "${a.value}"; file/user statements are not chemical identification by this tool.`
      : `User-declared sample equivalence: ${records.map(r => `"${r.left}" ↔ "${r.right}" (${r.basis})`).join('; ')}. This is a user assertion, not chemical identification by the tool.`);
    const ta = run?.conditions?.sampleType, tb = reference?.conditions?.sampleType;
    if (usable(ta) && usable(tb) && String(ta.value) !== String(tb.value))
      notes.push(`Sample types differ (${ta.value} vs ${tb.value}); type is contextual metadata, not identity. Comparability relies on the explicit sample declaration above.`);
  }
  return { comparable: reasons.length === 0, reasons, notes, identities: [a, b], equivalences: records || [] };
}

export function sampleGroupKey(session, run) {
  const identity = sampleIdentity(run);
  if (!identity.known) return null;
  const ids = new Set([identity.value]);
  for (const record of (session.sampleEquivalences || []).filter(validSampleEquivalence)) {
    ids.add(record.left); ids.add(record.right);
  }
  return [...ids].filter(id => pathBetween(session, identity.value, id) !== null).sort()[0];
}

export function declareSampleEquivalence(session, left, right, basis, idGen) {
  const a = clean(left), b = clean(right), note = clean(basis);
  if (!a || !b || a === b) throw new Error('Choose two different explicit sample/study IDs.');
  if (!note) throw new Error('State the evidence/basis for declaring these samples equivalent.');
  const stated = new Set(session.runs.map(sampleIdentity).filter(x => x.known).map(x => x.value));
  if (!stated.has(a) || !stated.has(b)) throw new Error('Both sample/study IDs must be explicitly recorded on runs in this session.');
  if ((session.sampleEquivalences || []).some(r => validSampleEquivalence(r) && ((r.left === a && r.right === b) || (r.left === b && r.right === a))))
    throw new Error('An equivalence declaration already exists for these sample/study IDs.');
  const record = { id: newId('sampleeq', idGen), left: a, right: b, basis: note, by: 'user', declaredAt: new Date().toISOString() };
  session.sampleEquivalences ||= [];
  session.sampleEquivalences.push(record);
  return record;
}

// Explicit analysis copies, never moves or changes to the Dashboard originals.
import {copyRunsToWorkspace,WORKSPACE_STAGES} from './workspaces.mjs';
export function prepareCompoundWorkspace(workspaces,ids){
 const dst=workspaces.retention,chosen=[...new Set(ids)],sources=chosen.map(id=>WORKSPACE_STAGES.map(stage=>({stage,run:workspaces[stage].runs.find(r=>r.id===id)})).find(x=>x.run));
 if(sources.some(x=>!x))return {ok:false,added:[],reason:'A selected run is no longer available. Nothing was copied.'};
 for(const x of sources){const prior=dst.runs.find(r=>r.id===x.run.id);if(prior&&JSON.stringify(prior.raw)!==JSON.stringify(x.run.raw))return {ok:false,added:[],reason:'An analysis record has the same ID but different raw evidence. Resolve this conflict before copying; nothing was overwritten.'};}
 const empty=dst.runs.length===0,added=[];
 for(const {stage,run}of sources)if(stage!=='retention')added.push(...copyRunsToWorkspace(workspaces,stage,'retention',[run.id]));
 if(empty&&added.length)dst.settings.specs=structuredClone(workspaces.equipment.settings.specs);
 for(const id of added)dst.runs.find(r=>r.id===id).flags.fit=true;
 return {ok:true,added,existing:chosen.length-added.length,reason:`${added.length} analysis copies added; ${chosen.length-added.length} existing analysis records kept. Dashboard originals, history and existing analysis work remain unchanged. No compound identities or t0 confirmations were inferred.`};
}

