 else if(d.status==='INVESTIGATE'||d.n===0)keys=['wavelength','acquisitionTime','injVolume'];
 else if(d.status==='RETENTION'||d.observeIntermediate)keys=['percentB'];
 else if(d.gradient)keys=['mode','percentB','flow','acquisitionTime'];
