export const GENERIC_BY_KEY = Object.fromEntries(GENERIC_FIELDS.map(f => [f.key, f]));
export const TIME_UNITS = { min: 1, s: 1 / 60 };
export const PRESSURE_UNITS = { psi: 1, bar: 14.5038, MPa: 145.038 };

const norm = s => String(s || '').trim().toLowerCase().replace(/\s+/g, '_');

export function readHeader(text) {
  const rows = csvRows(text);
  if (!rows.length) throw new Error('File is empty.');
  return { header: rows[0].map(h => h.trim()), rows: rows.slice(1) };
}

// Proposes header -> field mappings by exact canonical name or listed synonym.
export function autoMap(header) {
  const mapping = {};
  header.forEach((h, i) => {
    const n = norm(h);
    const f = GENERIC_FIELDS.find(g => norm(g.key) === n || g.synonyms.some(s => norm(s) === n));
    if (f && !(f.key in mapping)) mapping[f.key] = i;
  });
  return mapping;
}

export function looksLikeGeneric(text) {
  try { const { header } = readHeader(text); return 'rt' in autoMap(header); } catch { return false; }
}

// mapping: { fieldKey: columnIndex }, units: { time:'min'|'s', pressure:'psi'|'bar'|'MPa' }
export function parseGeneric(text, fileName, mapping, units = { time: 'min', pressure: 'psi' }) {
  let header, rows;
  try { ({ header, rows } = readHeader(text)); } catch (e) { return { ok: false, error: e.message }; }
  if (!('rt' in mapping)) return { ok: false, error: 'Required field "Retention time" is not mapped to a column.' };
  for (const [k, idx] of Object.entries(mapping)) if (!(idx >= 0 && idx < header.length)) return { ok: false, error: `Mapping for ${k} points to a column that does not exist.` };
  const tf = TIME_UNITS[units.time] ?? null, pf = PRESSURE_UNITS[units.pressure] ?? null;
  if (tf === null) return { ok: false, error: `Unsupported time unit "${units.time}".` };
  if (pf === null) return { ok: false, error: `Unsupported pressure unit "${units.pressure}".` };
  const get = (r, k) => (k in mapping) ? (r[mapping[k]] ?? '').trim() : '';
  const groups = new Map();
  rows.forEach((r, i) => {
    const key = ('run_key' in mapping) ? get(r, 'run_key') || '(blank run key)' : '(single run)';
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({ r, line: i + 2 });
  });
  const runs = [], errors = [];
  for (const [key, list] of groups) {
    const errs = [], warnings = [];
    const peaks = [];
    for (const { r, line } of list) {
      const rawRt = get(r, 'rt'); const rt = num(rawRt);
      if (rt === null) { errs.push(`line ${line}: retention time "${rawRt}" is not a number`); continue; }
      const val = (k, f = 1) => { const v = num(get(r, k)); return v === null ? null : v * f; };
      const mk = get(r, 'is_marker');
      peaks.push({ no: val('peak_no') ?? null, tR: rt * tf, area: val('area'), height: val('height'),
        widthBase: val('width_base', tf), widthHalf: val('width_half', tf), plates: val('plates'),
        exportedRs: val('exported_rs'), exportedK: null, mark: '', fileName: get(r, 'compound_label'),
        markerFlag: /^(y|yes|true|1)$/i.test(mk) });
    }
    peaks.sort((a, b) => a.tR - b.tR);
    for (let i = 1; i < peaks.length; i++) if (!(peaks[i].tR > peaks[i - 1].tR)) errs.push(`two peaks share retention time ${peaks[i].tR}`);
    peaks.forEach((p, i) => { if (p.no === null) p.no = i + 1; });
    for (const p of peaks) for (const k of ['widthBase', 'widthHalf', 'plates']) if (p[k] !== null && !(p[k] > 0)) errs.push(`peak at ${p.tR} min: ${k} must be positive`);
    // run-level fields must agree across the rows of a run
    const runVal = {};
    for (const f of GENERIC_FIELDS.filter(f => f.level === 'run' && f.key in mapping)) {
      const vals = [...new Set(list.map(({ r }) => get(r, f.key)).filter(v => v !== ''))];
      if (vals.length > 1) errs.push(`conflicting values for ${f.label}: ${vals.join(' / ')}`);
      runVal[f.key] = vals[0] ?? null;
    }
    if (errs.length) { errors.push({ runKey: key, errors: errs }); continue; }
    const n = k => num(runVal[k]);
    const conditions = {
      organic: cond(runVal.organic ? normaliseSolvent(runVal.organic) : null, 'mapping'),
      percentB: cond(n('percent_b'), 'mapping', { unit: '%' }),
      mode: cond(runVal.mode ? runVal.mode.toUpperCase() : null, 'mapping'),
      flow: cond(n('flow'), 'mapping', { unit: 'mL/min' }),
      ovenSetpoint: cond(n('oven_temp'), 'mapping', { unit: '°C', note: 'From the mapped CSV column; recorded as the column temperature.' }),
      injVolume: cond(n('inj_volume'), 'mapping', { unit: 'µL' }),
      wavelength: cond(n('wavelength'), 'mapping', { unit: 'nm' }),
      acquisitionTime: cond(n('acquisition_time') === null ? null : n('acquisition_time') * tf, 'mapping', { unit: 'min' }),
      phaseA: cond(runVal.phase_a, 'mapping'), phaseB: cond(runVal.phase_b, 'mapping'),
      mixAcnPct: cond(n('mix_acn_pct'), 'mapping', {unit:'% v/v of B bottle'}),
      additiveName: cond(runVal.additive, 'mapping'), additiveConc: cond(n('additive_conc'), 'mapping'), additiveUnit: cond(runVal.additive_unit, 'mapping'),
      pH: cond(n('ph'), 'mapping'),
      sampleId: cond(runVal.sample_id, 'mapping', { note: 'Explicit sample/study ID stated in the mapped CSV column. This is a file-author declaration, not chemical identification by the tool.' }),
      sampleType: cond(runVal.sample_type, 'mapping'), sampleConc: cond(n('sample_conc'), 'mapping', { unit: 'mg/mL' }),
    };
    for (const [k, f] of [['percent_b', [0, 100]], ['ph', [0, 14]]]) { const v = n(k); if (v !== null && (v < f[0] || v > f[1])) warnings.push(`${GENERIC_BY_KEY[k].label} ${v} is outside ${f[0]}–${f[1]}.`); }
    const pmax = n('pressure_max');
    const t0v = n('t0');
    runs.push({ runKey: key, measured: { peaks, trace: null,
      pressure: pmax === null ? null : { max: pmax * pf, mean: null, unit: 'psi', source: `mapped CSV column (converted from ${units.pressure})` },
      oven: null, room: null, acquisitionEnd: null },
      conditions, fileMeta: { sampleName: runVal.sample_name, columnLabel: runVal.column_label, instrumentLabel: runVal.instrument_label },
      documentedT0: t0v === null ? null : { t0: t0v * tf, note: runVal.t0_method || 'documented in the imported CSV (method not stated)' },
      warnings: [...warnings, 'Peak-table CSV: no chromatogram trace is available for this run, so it appears in tables but not in trace overlays.'] });
  }
  if (!runs.length) return { ok: false, error: errors.map(e => `${e.runKey}: ${e.errors.join('; ')}`).join(' | ') || 'No rows.' };
  return { ok: true, runs, partialErrors: errors, header };
}

export const TEMPLATE_HEADER = ['run_key', 'sample_name', 'peak_no', 'rt_min', 'area', 'height', 'width_base_min', 'width_half_min', 'plates', 'exported_rs', 'compound_label', 'is_marker', 'organic_solvent', 'percent_b', 'mode', 'flow_ml_min', 'oven_temp_c', 'inj_volume_ul', 'wavelength_nm', 'pressure_max_psi', 'acquisition_min', 't0_min', 't0_method', 'phase_a', 'phase_b', 'additive', 'additive_conc', 'additive_unit', 'ph', 'sample_type', 'sample_conc_mg_ml', 'column_label', 'instrument_label', 'sample_id','mix_acn_pct'];

// labsolutions.mjs — Shimadzu LabSolutions ASCII (CSV) export reader.
//
// Reads ONLY what the file states: the peak table, the detector trace, status
// traces (pump pressure, oven and room temperature), injection volume and file
// metadata. It never derives chemistry, column identity or instrument identity
// from the filename, the sample name or the method-file name. Those strings are
// kept as metadata so a user, or an explicitly selected import profile, can use
// them with stated provenance.
import { csvRows } from './csv.mjs';
import { num } from '../rules.mjs';
import { cond } from '../data-model/conditions.mjs';

export const FORMAT_ID = 'labsolutions';

export function looksLikeLabSolutions(text) {
  const head = String(text).slice(0, 4000);
  return /^﻿?\[Header\]/m.test(head) && /Application Name,\s*LabSolutions/i.test(head)
    || /\[Peak Table\(Detector [A-Z]\)\]/.test(String(text));
}

function sections(rows) {
  const out = new Map(); let cur = null;
  for (const r of rows) {
    const h = (r[0] || '').trim();
    if (/^\[.+\]$/.test(h) && r.slice(1).every(x => x.trim() === '')) { cur = h; if (!out.has(cur)) out.set(cur, []); else out.set(cur + '#dup', []); continue; }
    if (cur) out.get(cur).push(r);
  }
  return out;
}
const kv = (block, name) => { const r = (block || []).find(x => (x[0] || '').trim().toLowerCase() === name.toLowerCase()); return r ? (r[1] ?? '').trim() : null; };

function trace(block) {
  if (!block || !block.length) return null;
  const mult = num(kv(block, 'Intensity Multiplier')) ?? 1;
  const units = kv(block, 'Intensity Units') || '';
  const start = num(kv(block, 'Start Time(min)')), end = num(kv(block, 'End Time(min)'));
  const head = block.findIndex(r => (r[0] || '').trim() === 'R.Time (min)');
  if (head < 0) return { units, mult, start, end, t: [], y: [] };
  const t = [], y = [];
  for (const r of block.slice(head + 1)) { const a = num(r[0]), b = num(r[1]); if (a !== null && b !== null) { t.push(a); y.push(b * mult); } }
  return { units, mult, start, end, t, y };
}
const stats = y => y.length ? { mean: y.reduce((a, b) => a + b, 0) / y.length, min: Math.min(...y), max: Math.max(...y), n: y.length } : null;

// A status trace may begin before the separation does (oven warm-up,
// equilibration) and may run on after it. Where the exported timing allows it,
// the statistics are also computed over the ANALYSED INTERVAL — the window of
// the detector chromatogram — so warm-up before the separation is not reported
// as instability during it. The excluded points are counted, never discarded
// silently, and the window is stated. Where the timing does not allow it, the
// window is null and the caller must say that the whole trace was used.
function windowStats(tr, from, to) {
  if (!tr || !tr.t.length || from === null || from === undefined || to === null || to === undefined || !(to > from)) return null;
  const y = [], t = [];
  let before = 0, after = 0;
  for (let i = 0; i < tr.t.length; i++) {
    if (tr.t[i] < from) { before++; continue; }
    if (tr.t[i] > to) { after++; continue; }
    t.push(tr.t[i]); y.push(tr.y[i]);
  }
  const s = stats(y);
  if (!s) return null;
  // How well do the readings cover the interval? A small observed range tells
  // us nothing if there were only two readings, or if they stop a third of the
  // way through, so the gaps are measured and reported with the statistics.
  let maxGap = 0, gapAt = null;
  const span = to - from;
  const edges = [from, ...t, to];
  for (let i = 1; i < edges.length; i++) { const g = edges[i] - edges[i - 1]; if (g > maxGap) { maxGap = g; gapAt = [edges[i - 1], edges[i]]; } }
  return { ...s, from, to, excludedBefore: before, excludedAfter: after, firstT: t[0], lastT: t.at(-1),
    span, maxGap, maxGapFraction: span > 0 ? maxGap / span : null, maxGapAt: gapAt };
}

// The file states a LOCAL calendar time, not a UTC instant. Both minute and
// second precision occur in LabSolutions exports. Keep that precision and do
// not let Date normalise impossible dates (31 February) or invent a timezone.
export function parseAcquiredTimestamp(value) {
  const raw = value === null || value === undefined ? null : String(value);
  const unknown = reason => ({ raw, valid: false, local: null, precision: null,
    timezone: null, timezoneRecorded: false, components: null, reason });
  if (!raw || !raw.trim()) return unknown('No acquisition time is recorded in the file.');
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?$/i.exec(raw.trim());
  if (!m) return unknown('Acquisition time is recorded but its format is unsupported; expected D/M/YYYY H:mm[:ss] with optional AM/PM. No timezone is stated.');
  const [, ds, ms, ys, hs, mins, secs, ap] = m;
  const day = Number(ds), month = Number(ms), year = Number(ys), minute = Number(mins);
  const second = secs === undefined ? null : Number(secs);
  let hour = Number(hs);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (year < 1 || month < 1 || month > 12 || day < 1 || day > (days[month - 1] || 0))
    return unknown('Acquisition time has an invalid calendar date; it was not normalised to a different day.');
  if (minute > 59 || (second !== null && second > 59) || (ap ? hour < 1 || hour > 12 : hour > 23))
    return unknown('Acquisition time has an invalid hour/minute/second or AM/PM value.');
  if (ap) { if (/pm/i.test(ap) && hour < 12) hour += 12; if (/am/i.test(ap) && hour === 12) hour = 0; }
  const pad = n => String(n).padStart(2, '0');
  const precision = second === null ? 'minute' : 'second';
  const local = `${ys}-${pad(month)}-${pad(day)}T${pad(hour)}:${pad(minute)}${second === null ? '' : `:${pad(second)}`}`;
  return { raw, valid: true, local, precision, timezone: null, timezoneRecorded: false,
    components: { year, month, day, hour, minute, second },
    reason: `Local calendar time recorded to ${precision} precision. Timezone is NOT RECORDED; no UTC conversion or missing seconds have been inferred.` };
}

// A folder explicitly named CYCLE-N is a source-folder statement. It is not
// inferred from the HPLC-number token, from chromatography or from a run name;
// it neither completes that cycle nor chooses the engine's next action.
export function sourceCycleFromPaths(paths = []) {
  const evidence = [];
  for (const { field, path } of paths) {
    if (typeof path !== 'string' || !/[\\/]/.test(path)) continue;
    const folders = path.split(/[\\/]/).filter(Boolean).slice(0, -1);
    for (const segment of folders) {
      const match = /^CYCLE[-_\s]+(\d{1,2})(?=$|\s|[(_-])/i.exec(segment.trim());
      if (match) evidence.push({ field, path, segment, cycle: Number(match[1]) });
    }
  }
  const cycles = [...new Set(evidence.map(e => e.cycle))];
  const names = { 0: 'Equipment', 1: 'Retention', 2: 'Selectivity', 3: 'Efficiency', 4: 'Gradient' };
  const cycle = cycles.length === 1 ? cycles[0] : null;
  return { status: !cycles.length ? 'not-recorded' : cycles.length > 1 ? 'conflict' : 'recorded', cycle,
    label: cycle === null ? null : `Cycle ${cycle}${names[cycle] ? ` — ${names[cycle]}` : ''}`,
    evidence, note: !cycles.length ? 'No explicit CYCLE-N source folder is recorded in the original file paths.'
      : cycles.length > 1 ? 'Original file paths name different cycles; no source cycle was selected.'
      : 'Source folder as stated in the original export, not proof of experiment purpose, completed-cycle status or the next decision route.' };
}

export function baseName(p) { return String(p || '').replace(/^.*[\\/]/, '').replace(/\.(lcd|csv|txt)$/i, ''); }

// Returns {ok, run:{measured, conditions, fileMeta, warnings}, error}
export function parseLabSolutions(text, fileName) {
  let rows;
  try { rows = csvRows(text); } catch (e) { return { ok: false, error: e.message }; }
  const sec = sections(rows);
  const peakKeys = [...sec.keys()].filter(k => /^\[Peak Table\(Detector [A-Z]\)\]/.test(k));
  if (!peakKeys.length) return { ok: false, error: 'No [Peak Table(Detector …)] section found; this is not a LabSolutions peak export.' };
  const warnings = [];
  if (peakKeys.length > 1) warnings.push(`File contains ${peakKeys.length} detector peak tables; only ${peakKeys[0]} was read.`);
  const block = sec.get(peakKeys[0]);
  const detector = /Detector ([A-Z])/.exec(peakKeys[0])[1];
  const declared = num(kv(block, '# of Peaks'));
  const hi = block.findIndex(r => (r[0] || '').trim() === 'Peak#');
  if (declared === null) return { ok: false, error: 'Peak table has no "# of Peaks" line.' };
  if (hi < 0 && declared !== 0) return { ok: false, error: 'Peak table has no "Peak#" header row.' };
  const header = hi < 0 ? [] : block[hi].map(x => x.trim());
  const col = name => header.indexOf(name);
  if (declared > 0 && col('R.Time') < 0) return { ok: false, error: 'Peak table lacks the required R.Time column.' };
  const peaks = [];
  for (const r of hi < 0 ? [] : block.slice(hi + 1)) {
    if (!/^\d+$/.test((r[0] || '').trim())) continue;
    const g = n => col(n) < 0 ? null : num(r[col(n)]);
    peaks.push({ no: Number(r[0]), tR: g('R.Time'), area: g('Area'), height: g('Height'),
      plates: g('Plate #'), exportedRs: g('Resolution'), exportedK: g("k'"), tailing: g('Tailing'),
      widthBase: null, widthHalf: null,
      mark: col('Mark') < 0 ? '' : (r[col('Mark')] || '').trim(), fileName: col('Name') < 0 ? '' : (r[col('Name')] || '').trim() });
  }
  if (peaks.length !== declared) return { ok: false, error: `Peak count mismatch: header declares ${declared}, ${peaks.length} peak rows read.` };
  if (peaks.some(p => p.tR === null)) return { ok: false, error: 'A peak lacks a numeric retention time.' };
  for (let i = 1; i < peaks.length; i++) if (!(peaks[i].tR > peaks[i - 1].tR)) return { ok: false, error: `Retention times are not strictly increasing at peak ${peaks[i].no}.` };
  if (col('Plate #') < 0) warnings.push('No "Plate #" column: plate-derived resolution is unavailable for this file.');
  if (col('Resolution') < 0) warnings.push('No "Resolution" column: exported resolution is unavailable for this file.');

  const chromKey = [...sec.keys()].find(k => k.startsWith(`[LC Chromatogram(Detector ${detector}`)) || [...sec.keys()].find(k => k.startsWith('[LC Chromatogram('));
  const tr = chromKey ? trace(sec.get(chromKey)) : null;
  const pres = trace(sec.get('[LC Status Trace(Pump A Pressure)]'));
  const oven = trace(sec.get('[LC Status Trace(Oven Temp.)]'));
  const room = trace(sec.get('[LC Status Trace(Room Temp.)]'));
  const ps = pres ? stats(pres.y) : null, os = oven ? stats(oven.y) : null, rs = room ? stats(room.y) : null;

  const H = sec.get('[Header]'), S = sec.get('[Sample Information]'), O = sec.get('[Original Files]'), C = sec.get('[Configuration]');
  const acquiredTimestamp = parseAcquiredTimestamp(kv(S, 'Acquired'));
  const fileMeta = {
    application: kv(H, 'Application Name'), version: kv(H, 'Version'),
    dataFileName: kv(H, 'Data File Name'), sampleName: kv(S, 'Sample Name'), sampleId: kv(S, 'Sample ID'),
    acquired: kv(S, 'Acquired'), acquiredIso: acquiredTimestamp.local,
    acquiredPrecision: acquiredTimestamp.precision, acquiredTimezone: null, acquiredTimestamp,
    originalDataFileName: kv(O, 'Data File'),
    methodFileName: kv(O, 'Method File'), instrumentName: kv(C, 'Instrument Name'),
    vial: kv(S, 'Vial#'), detector: `Detector ${detector}`,
    chromatogramChannel: chromKey || null,
  };
  const fBase = baseName(fileName), sBase = baseName(fileMeta.sampleName), dBase = baseName(fileMeta.dataFileName);
  const stripCopy = s => s.replace(/\s*\(\d+\)$/, '');
  fileMeta.nameSources = { fileName: { value: fileName || null, base: fBase, source: 'uploaded filename' },
    sampleName: { value: fileMeta.sampleName, base: sBase, source: '[Sample Information] Sample Name' },
    dataFileName: { value: fileMeta.dataFileName, base: dBase, source: '[Header] Data File Name' } };
  fileMeta.nameConflicts = [];
  if (fileMeta.sampleName && stripCopy(fBase) !== stripCopy(sBase)) {
    fileMeta.nameConflicts.push({ left: 'fileName', right: 'sampleName', leftValue: fileName || null, rightValue: fileMeta.sampleName,
      leftBase: fBase, rightBase: sBase, kind: 'different-recorded-names', resolved: false });
    warnings.push(`NAME CONFLICT: the file is named "${fBase}" but its internal Sample Name is "${sBase}". Neither name is used to set conditions unless an import profile is explicitly selected; select the source and record why it describes this injection. Original strings are kept unchanged.`);
  }
  if (fileMeta.dataFileName && stripCopy(dBase) !== stripCopy(sBase) && fileMeta.sampleName) {
    fileMeta.nameConflicts.push({ left: 'dataFileName', right: 'sampleName', leftValue: fileMeta.dataFileName, rightValue: fileMeta.sampleName,
      leftBase: dBase, rightBase: sBase, kind: 'different-recorded-names', resolved: false });
    warnings.push(`NAME CONFLICT: internal Data File Name "${dBase}" differs from Sample Name "${sBase}".`);
  }
  fileMeta.sourceCycle = sourceCycleFromPaths([{ field: '[Header] Data File Name', path: fileMeta.dataFileName },
    { field: '[Original Files] Data File', path: fileMeta.originalDataFileName },
    { field: '[Original Files] Method File', path: fileMeta.methodFileName }]);
  if (fileMeta.sourceCycle.status === 'conflict') warnings.push(`SOURCE CYCLE CONFLICT: ${fileMeta.sourceCycle.note}`);
  if (fileMeta.acquired && !acquiredTimestamp.valid) warnings.push(`ACQUISITION TIME NOT USED FOR ORDERING: ${acquiredTimestamp.reason} Original value: "${fileMeta.acquired}".`);
  if (fileMeta.methodFileName) warnings.push(`Method file recorded as "${baseName(fileMeta.methodFileName)}". Method-file names are shown for reference only and are never used to set conditions.`);

  const injV = num(kv(S, 'Injection Volume'));
  const conditions = {
    injVolume: cond(injV, 'file', { unit: 'µL', note: 'From [Sample Information] Injection Volume; the export does not state the unit (µL assumed as the LabSolutions convention).' }),
    acquisitionTime: cond(tr && tr.end !== null ? tr.end : null, 'file', { unit: 'min', note: `End time of ${chromKey || 'chromatogram'} block.` }),
  };
  const measured = {
    peaks,
    trace: tr && tr.t.length ? { t: tr.t, y: tr.y, unit: tr.units || 'intensity', channel: chromKey } : null,
    pressure: ps ? { max: ps.max, mean: ps.mean, min: ps.min, unit: pres.units || 'unknown', source: 'file: [LC Status Trace(Pump A Pressure)] × Intensity Multiplier', series: {t:[...pres.t],y:[...pres.y]} } : null,
    oven: os ? { ...os, unit: oven.units || 'C', source: 'file: [LC Status Trace(Oven Temp.)] (oven sensor)',
      span: oven.t.length ? { from: oven.t[0], to: oven.t.at(-1) } : null,
      window: windowStats(oven, tr?.t?.length ? tr.t[0] : tr?.start ?? null, tr?.t?.length ? tr.t.at(-1) : tr?.end ?? null),
      windowSource: tr ? `the detector chromatogram window of ${chromKey || 'the trace'}` : null,
      series: downsample(oven.t, oven.y, 300) } : null,
    room: rs ? { ...rs, unit: room.units || 'C', source: 'file: [LC Status Trace(Room Temp.)]' } : null,
    acquisitionEnd: tr ? tr.end : null,
  };
  if (!measured.trace) warnings.push('No chromatogram trace in the file; overlays are unavailable for this run.');
  if (!measured.pressure) warnings.push('No pump-pressure trace in the file; the pressure check needs a user-entered value.');
  return { ok: true, run: { measured, conditions, fileMeta, warnings } };
}

function downsample(t, y, n) {
  if (t.length <= n) return { t: [...t], y: [...y] };
  const step = Math.ceil(t.length / n), ot = [], oy = [];
  for (let i = 0; i < t.length; i += step) { ot.push(t[i]); oy.push(y[i]); }
  return { t: ot, y: oy };
}

// profiles.mjs — OPTIONAL, EXPLICITLY SELECTED import profiles.
//
// A profile interprets a naming convention. It is never applied automatically.
// Its outputs carry source "profile:<id>" and confirmed:false until the user
// confirms them. A string that does not match the convention exactly produces
// no values at all (no partial guessing).
//
// Profile 'monashplc-runname': the BPS2032 RUN NAME convention taught in the
// Equipment LAB deck slides 44–47:
//   GR##-Injection#-HPLC#-Solvent-pH-ISO|GRA-%B-Flow-InjVol(u)-SampleType-Conc-
//   ColumnCode-LxIDxdp-Temperature-Wavelength
// e.g. "GR00-01-6-ACN-3-ISO-50-1.50-20u-CP-0.1-C18nP-150x4.6x5-amb-254".
// The column code, geometry and HPLC number are REPORTED, never turned into a
// column or instrument association. A user may define an explicit code map.
import { num } from '../rules.mjs';
import { cond, normaliseSolvent } from '../data-model/conditions.mjs';
import { cite } from '../presets/sources.mjs';
import { baseName } from './labsolutions.mjs';

export const PROFILES = {
  'monashplc-runname': {
    id: 'monashplc-runname', label: 'BPS2032 run-name convention (Equipment LAB slides 44–47)',
    source: cite('EQ-LAB', 'slides 44–47 and notes (experiment file naming)'),
    description: 'Reads conditions from a run name written in the BPS2032 convention. Values are marked as coming from this profile and stay unconfirmed until you confirm them. "amb" is recorded as "no oven setpoint", not as a temperature.',
  },
};

const RX = {
  group: /^GR\d{1,3}$/i, inj: /^\d{1,3}$/, hplc: /^\d{1,2}$/, solvent: /^[A-Za-z]{2,10}$/, pH: /^\d{1,2}(\.\d+)?$/,
  mode: /^(ISO|GRA)$/i, b: /^\d{1,3}(\.\d+)?$/, flow: /^\d+(\.\d+)?$/, vol: /^\d+(\.\d+)?u$/i, type: /^[A-Za-z]{2,4}$/,
  conc: /^\d+(\.\d+)?$/, code: /^[A-Za-z0-9]{2,12}$/, dims: /^\d+(\.\d+)?x\d+(\.\d+)?x\d+(\.\d+)?$/i, temp: /^(amb|T?\d{1,3})$/i, wl: /^(\d{3}|PDA)$/i,
};
const ORDER = ['group', 'inj', 'hplc', 'solvent', 'pH', 'mode', 'b', 'flow', 'vol', 'type', 'conc', 'code', 'dims', 'temp', 'wl'];

export function parseRunName(str) {
  const base = baseName(str).replace(/\s*\(\d+\)$/, '').trim();
  let tokens = base.split('-'),gradient=null;
  // Course gradient names replace the single ISO %B token with initial-final-tG.
  if(tokens.length===17&&/^GRA$/i.test(tokens[5])){
    const [initialB,finalB,tG]=[tokens[6],tokens[7],tokens[8].replace(/min$/i,'')].map(num);
    if(!RX.b.test(tokens[6])||!RX.b.test(tokens[7])||!/^\d+(\.\d+)?(min)?$/i.test(tokens[8])||!(initialB>=0&&finalB>initialB&&finalB<=100&&tG>0))return {ok:false,reason:'Invalid gradient initial / final %B or ramp time.'};
    gradient={initialB,finalB,tG,source:'Course run-name initial-final-ramp convention; holds and dwell volume not recorded'};
    tokens=[...tokens.slice(0,7),...tokens.slice(9)];
  }
  if (tokens.length !== ORDER.length) return { ok: false, reason: `"${base}" has ${tokens.length} dash-separated tokens; the convention has ${ORDER.length}.` };
  const t = {};
  for (let i = 0; i < ORDER.length; i++) {
    if (!RX[ORDER[i]].test(tokens[i])) return { ok: false, reason: `Token ${i + 1} "${tokens[i]}" does not match the ${ORDER[i]} field of the convention.` };
    t[ORDER[i]] = tokens[i];
  }
  const b = num(t.b);
  if (b > 100) return { ok: false, reason: `%B token ${t.b} exceeds 100.` };
  const [L, ID, dp] = t.dims.toLowerCase().split('x').map(num);
  const ambient = /^amb$/i.test(t.temp);
  return { ok: true, base, tokens: t, values: {
    group: t.group.toUpperCase(), injectionNo: Number(t.inj), hplcNo: Number(t.hplc), organic: normaliseSolvent(t.solvent),
    pH: num(t.pH), mode: t.mode.toUpperCase(), percentB: b, gradient, flow: num(t.flow), injVolume: num(t.vol.replace(/u$/i, '')),
    sampleType: t.type.toUpperCase(), sampleConc: num(t.conc), columnCode: t.code, geometry: { lengthMm: L, idMm: ID, particleUm: dp },
    ovenSetpoint: ambient ? 'ambient' : num(t.temp.replace(/^T/i, '')), wavelength: /^PDA$/i.test(t.wl) ? 'PDA' : num(t.wl) } };
}

// Both names remain file metadata. Selecting one is an explicit interpretation
// of that convention, not a correction to the CSV or a sample identity claim.
export function runNameSourceOptions(run) {
  const fileMeta = run.measured?.fileMeta || {};
  const sources = [{ from: 'fileName', label: 'Uploaded filename', rawName: run.raw?.fileName || null },
    { from: 'sampleName', label: 'Internal Sample Name', rawName: fileMeta.sampleName || null }]
    .map(s => ({ ...s, base: baseName(s.rawName).replace(/\s*\(\d+\)$/, ''), parsed: parseRunName(s.rawName) }));
  const [file, sample] = sources;
  const conflicts = file.parsed.ok && sample.parsed.ok
    ? Object.keys(file.parsed.values).filter(k => JSON.stringify(file.parsed.values[k]) !== JSON.stringify(sample.parsed.values[k]))
      .map(field => ({ field, fileName: file.parsed.values[field], sampleName: sample.parsed.values[field] })) : [];
  const nameConflict = !!(sample.rawName && file.base !== sample.base)
    || !!fileMeta.nameConflicts?.length;
  return { sources, conflicts, nameConflict,
    note: 'Source choice does not identify compounds, establish same-sample identity, rename a run or rewrite original CSV text.' };
}

function originalNames(run) {
  return { fileName: run.raw?.fileName || null, sampleName: run.measured?.fileMeta?.sampleName || null,
    dataFileName: run.measured?.fileMeta?.dataFileName || null };
}

export function profileConfirmationStatus(run) {
  const options = runNameSourceOptions(run);
  if (!options.nameConflict) return { ok: true, reason: 'No conflicting recorded run-name sources.' };
  const record = run.profileResolution;
  const matching = record && record.profile === 'monashplc-runname' && record.by === 'user'
    && ['fileName', 'sampleName'].includes(record.from) && typeof record.basis === 'string' && !!record.basis.trim()
    && typeof record.declaredAt === 'string' && Number.isFinite(Date.parse(record.declaredAt))
    && JSON.stringify(record.originalNames) === JSON.stringify(originalNames(run))
    && record.from === run.profileReport?.from;
  return { ok: !!matching, reason: matching
    ? `User selected ${record.from === 'sampleName' ? 'the internal Sample Name' : 'the uploaded filename'}: ${record.basis}. Original names are unchanged; this does not identify compounds or the sample.`
    : 'Recorded names disagree. Select filename or internal Sample Name and record the basis before confirming profile-derived conditions.' };
}

// Apply the profile to an imported run. `from` = 'fileName' | 'sampleName'.
// codeMaps = { column: {code: physicalColumnId}, instrument: {hplcNo: instrumentId} } — user-defined.
export function applyRunNameProfile(run, { from = 'fileName', codeMaps = {} } = {}) {
  const src = 'profile:monashplc-runname';
  const fileStr = run.raw.fileName, sampleStr = run.measured.fileMeta?.sampleName;
  const choices = runNameSourceOptions(run);
  const primary = parseRunName(from === 'sampleName' ? sampleStr : fileStr);
  const other = parseRunName(from === 'sampleName' ? fileStr : sampleStr);
  const report = { profile: 'monashplc-runname', from, applied: false, messages: [],
    selectedName: from === 'sampleName' ? sampleStr || null : fileStr || null,
    sourceOptions: choices.sources.map(({ from, label, rawName, parsed }) => ({ from, label, rawName, readable: parsed.ok, reason: parsed.reason || null })),
    nameConflict: choices.nameConflict, conflicts: choices.conflicts };
  if (!['fileName', 'sampleName'].includes(from)) { report.messages.push('Profile not applied: choose fileName or sampleName explicitly.'); run.profileReport = report; return report; }
  if (!primary.ok) { report.messages.push(`Profile not applied: ${primary.reason}`); run.profileReport = report; return report; }
  const v = primary.values;
  const set = (k, value, unit = '', note = '') => {
    // never overwrite a value that came from the file itself or from the user
    const cur = run.conditions[k];
    if (cur && cur.value !== null && (cur.source === 'file' || cur.source === 'user' || cur.source === 'mapping')) {
      if (String(cur.value) !== String(value)) report.messages.push(`CONFLICT on ${k}: file/user value ${cur.value} kept; profile reads ${value}.`);
      return;
    }
    run.conditions[k] = cond(value, src, { unit, confirmed: false, note: note || `Read from ${from === 'sampleName' ? 'sample name' : 'filename'} by the run-name profile.` });
  };
  set('organic', v.organic); set('pH', v.pH); set('mode', v.mode); set('percentB', v.percentB, '%');
  set('flow', v.flow, 'mL/min'); set('injVolume', v.injVolume, 'µL'); set('sampleType', v.sampleType);
  set('sampleConc', v.sampleConc, 'mg/mL'); set('wavelength', v.wavelength, 'nm');
  set('ovenSetpoint', v.ovenSetpoint, '°C', v.ovenSetpoint === 'ambient' ? '"amb" in the run name: no oven setpoint. This is NOT a temperature value.' : '');
  run.profileExtras = { group: v.group, injectionNo: v.injectionNo, hplcNo: v.hplcNo, columnCode: v.columnCode, geometry: v.geometry, gradient:v.gradient, source: src, parsedFrom: from };
  const link = (key, target) => {
    const cur = run.assoc[key];
    if (cur?.value && !String(cur.source || '').startsWith('profile:')) {
      if (target && cur.value !== target) report.messages.push(`CONFLICT on ${key}: the existing non-profile equipment association was kept; the selected profile/code map points to ${target}.`);
      return;
    }
    // Switching sources must not leave a code-map association from the old
    // interpretation behind. No code map means no equipment association.
    run.assoc[key] = target ? { value: target, source: `${src} + user code map`, confirmed: false }
      : { value: null, source: null, confirmed: false };
  };
  link('columnId', codeMaps.column?.[v.columnCode]);
  link('instrumentId', codeMaps.instrument?.[v.hplcNo]);
  if (other.ok) {
    const diffs = Object.keys(v).filter(k => JSON.stringify(v[k]) !== JSON.stringify(other.values[k]));
    if (diffs.length) report.messages.push(`Filename and sample name differ in: ${diffs.join(', ')}. Values were read from the ${from === 'sampleName' ? 'sample name' : 'filename'} as selected; confirm which describes the injection.`);
  }
  report.applied = true;
  run.profileReport = report;
  report.confirmation = profileConfirmationStatus(run);
  if (!report.confirmation.ok) report.messages.push(`PROFILE VALUES UNCONFIRMED: ${report.confirmation.reason}`);
  return report;
}

// Explicit resolution is a user annotation. It records who chose which
// unchanged source and why; values remain unconfirmed until the separate
// confirmation action. File/user/mapped conditions still take precedence.
export function resolveRunNameProfile(run, { from, basis, codeMaps = {} } = {}) {
  const note = typeof basis === 'string' ? basis.trim() : '';
  if (!['fileName', 'sampleName'].includes(from)) throw new Error('Select uploaded filename or internal Sample Name.');
  if (!note) throw new Error('Record the basis for choosing this run-name source.');
  const choice = runNameSourceOptions(run).sources.find(s => s.from === from);
  if (!choice?.parsed.ok) throw new Error(`The selected source cannot be read by the run-name profile: ${choice?.parsed.reason || 'not recorded'}`);
  const record = { profile: 'monashplc-runname', from, basis: note, originalNames: originalNames(run),
    by: 'user', declaredAt: new Date().toISOString() };
  run.profileResolution = record;
  const report = applyRunNameProfile(run, { from, codeMaps });
  report.resolution = { ...record };
  for (const c of Object.values(run.conditions)) if (c?.value !== null && String(c?.source || '').startsWith('profile:'))
    c.note = `${c.note || ''} Source choice declared by user: ${note}. This does not establish compound or sample identity.`.trim();
  return report;
}

// Confirm profile-derived values on a run (the user's explicit action).
export function confirmProfileValues(run) {
  const status = profileConfirmationStatus(run);
  if (!status.ok) {
    const warning = `PROFILE CONFIRMATION REFUSED: ${status.reason}`;
    if (!run.warnings.includes(warning)) run.warnings.push(warning);
    return 0;
  }
  let n = 0;
  for (const c of Object.values(run.conditions)) if (c && c.value !== null && String(c.source || '').startsWith('profile:') && !c.confirmed) { c.confirmed = true; c.note = (c.note ? c.note + ' ' : '') + 'Confirmed by user.'; n++; }
  for (const a of Object.values(run.assoc)) if (a && a.value && String(a.source || '').startsWith('profile:') && !a.confirmed) { a.confirmed = true; n++; }
  return n;
}

