// analysis.mjs — the step-by-step Retention analysis (12 items) and the
// retention-side next-experiment options. Pure: returns a structured result.
import { fitEligibility, percentBSummary } from './eligibility.mjs';
import { fitCompounds } from './fit.mjs';
import { evaluateCandidates, intermediateB, predictTR } from './candidates.mjs';
import { positionHypotheses } from './exploratory.mjs';
import { peakStatus, missingCompounds, orderChanges } from '../alignment/correspondence.mjs';
import { LOG_CONVENTION,toPsi } from '../rules.mjs';
import { usable } from '../data-model/conditions.mjs';
import { runColumn, runInstrument, effectiveTemperature } from '../data-model/derive.mjs';
import { columnLimit } from '../data-model/equipment.mjs';
import { documentedLimitStatus, repeatLimitCheck } from '../data-model/limits.mjs';

const measuredP = run => {const p=run?.measured?.pressure,c=toPsi(p?.max,p?.unit);return c.ok?c.psi:null;};
const recordedT = (run, settings) => { const t = effectiveTemperature(run, settings); return t.known ? t.value : null; };

export function retentionAnalysis(session, settings) {
  const spec = settings.specs.lastPeak;
  const elig = fitEligibility(session, settings);
  const ref = elig.reference;
  const eligible = elig.runs.filter(e => e.eligible);
  const res = { status: 'not-started', reasons: [], evidence: [], assumptions: [LOG_CONVENTION, 'K = (tR − t0) / t0 with tR and t0 in minutes.'], missing: [],
    steps: {lastPeakSpec:{...spec}}, issued: null, subset: null, exploratory: null, intermediate: null, plan: null, fits: null, eligibility: elig };

  // 1–3 selection, eligibility, comparability
  res.steps.selected = elig.runs.map(e => ({ label: e.label, runId: e.runId, percentB: e.percentB, isReference: e.isReference }));
  res.steps.eligibility = elig.runs.map(e => ({ label: e.label, eligible: e.eligible, reasons: e.reasons, notes: e.notes }));
  if (elig.referenceUncertain) { res.assumptions.push(`Fit reference: ${elig.referenceBasis}.`); res.missing.push('Acquisition order of the runs in the retention fit, or an explicitly selected fit reference run.'); }
  res.steps.comparability = ref ? { reference: ref.label, referenceBasis: elig.referenceBasis, rule: `Same physical column, organic solvent and isocratic mode; temperatures known and within ${settings.tempMatchTolerance} °C; pH/additive/phase A equal where recorded. Unknown values never match.` } : null;
  // 4 t0
  res.steps.t0 = elig.runs.map(e => ({ label: e.label, ok: e.t0.ok, method: e.t0.method, t0: e.t0.t0 ?? null, text: e.t0.text, proxy: !!e.t0.proxy }));

  if (!elig.runs.length) { res.status = 'not-started'; res.missing.push('Tick "Include in retention fit" for the runs of your %B series.'); res.reasons.push('No run is selected for the retention fit.'); return res; }

  // 5 mapping
  const analytes = session.compounds.filter(c => c.role !== 'marker');
  res.steps.mapping = eligible.map(e => ({ label: e.label, peaks: peakStatus(session, e.run), missing: missingCompounds(session, e.run).map(c => c.name) }));
  res.steps.orderChanges = orderChanges(session, eligible.map(e => e.run)).map(o => ({ a: session.compounds.find(c => c.id === o.a)?.name, b: session.compounds.find(c => c.id === o.b)?.name, runs: o.runs.map(r => r.label) }));

  if (eligible.length < 2) {
    res.status = 'need-information';
    res.reasons.push(`${eligible.length} of ${elig.runs.length} selected run(s) are eligible; at least two comparable runs at different %B are needed for a line.`);
    for (const e of elig.runs.filter(x => !x.eligible)) res.missing.push(`${e.label}: ${e.reasons.join('; ')}`);
    return res;
  }

  const t0Ref = elig.runs.find(e => e.isReference)?.t0;
  const t0Proposed = t0Ref?.ok ? t0Ref.t0 : null;
  const confirmedAny = session.assignments.some(a => a.state === 'confirmed' && eligible.some(e => e.runId === a.runId));
  if (!analytes.length || !confirmedAny) {
    res.status = 'mapping-unresolved';
    res.reasons.push(!analytes.length ? 'No compounds are defined, so no peak can be identified.' : 'No peak in the eligible runs has a confirmed compound identity.');
    res.missing.push('Define the compounds (Retention → Compounds) and assign peaks to them in each eligible run, or accept proposals you have checked.');
    res.exploratory = positionHypotheses(session, settings, elig.runs, t0Proposed, spec);
    res.steps.kData = []; res.steps.fits = [];
    return res;
  }

  // 6–9 K data, fits, residuals, missing compounds
  const fits = fitCompounds(session, settings, elig);
  res.fits = fits;
  res.steps.kData = fits.results.map(r => ({ compound: r.compound.name, points: r.points, excluded: r.excluded }));
  res.steps.fits = fits.results.map(r => ({ compound: r.compound.name, ok: r.fit.ok, slope: r.fit.slope, intercept: r.fit.intercept, S: r.course?.S, a: r.course?.a, r2: r.fit.r2, n: r.fit.n, range: r.fit.ok ? [r.fit.xMin, r.fit.xMax] : null, adequate: r.adequate, quality: r.quality.statement, reasons: r.reasons, proxy: r.proxy }));
  res.steps.residuals = fits.results.filter(r => r.fit.ok).map(r => ({ compound: r.compound.name, residuals: r.fit.residuals.map(x => ({ percentB: x.x, residual: x.residual, run: x.runLabel })), maxAbs: r.fit.maxAbsResidual }));
  res.steps.missing = fits.results.filter(r => !r.adequate).map(r => ({ compound: r.compound.name, why: r.reasons.length ? r.reasons : ['no points'], missingIn: r.missingIn }));
  res.evidence.push(`${fits.eligibleCount} eligible run(s); ${fits.coverage.adequate} of ${fits.coverage.expected} defined analyte(s) adequately modelled under "${fits.policy.label}".`);
  if (fits.anyProxy) res.assumptions.push('At least one point uses the opt-in FIRST-PEAK PROXY for t0 (unconfirmed). Every result below is exploratory.');

  // 10–12 candidate evaluation
  if (!(t0Proposed > 0)) { res.status = 'need-information'; res.missing.push('The fit reference run has no established t0, so retention times at candidate %B cannot be predicted.'); return res; }
  const adequate = fits.results.filter(r => r.adequate).map(r => ({ compoundId: r.compound.id, name: r.compound.name, fit: r.fit }));
  const anyFit = fits.results.filter(r => r.fit.ok && r.fit.slope < 0).map(r => ({ compoundId: r.compound.id, name: r.compound.name, fit: r.fit }));
  res.steps.t0Proposed = { t0: t0Proposed, from: ref.label, text: t0Ref.text };
  const deficient = fits.results.filter(r => r.fit.ok && !r.adequate);

  if (adequate.length) {
    const ev = evaluateCandidates(adequate, t0Proposed, spec);
    const block = { candidates: ev, lines: adequate.map(a => a.name), coverage: fits.coverage };
    if (fits.coverage.complete && !fits.anyProxy) { res.issued = block; res.status = 'model-ready'; }
    else { res.subset = block; res.status = deficient.length ? 'fit-deficient' : 'subset-model'; }
    if (ev.ok && ev.minimum) {
      const upper = Math.max(...adequate.map(a => a.fit.xMax));
      res.intermediate = intermediateB(adequate, t0Proposed, ev.minimum.B, Math.max(upper, ev.minimum.B));
    }
  } else res.status = deficient.length ? 'fit-deficient' : 'mapping-unresolved';
  if (anyFit.length && (deficient.length || !fits.coverage.complete || fits.anyProxy)) {
    res.exploratory = { kind: 'all fitted lines, including those that fail the policy', candidates: evaluateCandidates(anyFit, t0Proposed, spec), lines: anyFit.map(a => a.name),
      label: 'EXPLORATORY — includes lines that do not satisfy the selected fit-quality policy, or covers only part of the sample. Not issued.' };
  }
  if (!fits.coverage.definedComplete) res.reasons.push(`Compound coverage is incomplete: ${fits.coverage.adequate} of ${fits.coverage.expected} analytes adequately modelled (missing: ${fits.coverage.missing.join(', ')}). A minimum from a subset is NOT a whole-sample minimum.`);
  if (fits.coverage.sampleReason) {
    res.reasons.push(`Unidentified peaks: ${fits.coverage.sampleReason}`);
    res.missing.push(`Confirm an identity for, define a compound for, or mark as an artefact: ${fits.coverage.unattributed.map(u => `${u.runLabel} peak ${u.peakNo}`).join(', ')}.`);
  }
  if (deficient.length) res.reasons.push(`${deficient.length} compound line(s) do not satisfy the selected fit policy: ${deficient.map(d => `${d.compound.name} (${d.reasons.join('; ')})`).join(' | ')}.`);
  if (res.status === 'model-ready') res.reasons.push(`All ${fits.coverage.expected} analytes are adequately modelled; ${res.issued.candidates.explanation}`);
  if (deficient.length || (res.status !== 'model-ready' && fits.results.some(r => r.fit.ok)))
    res.plan = retentionPlan(session, settings, { elig, eligible, fits, deficient, t0Proposed, spec, ref, exploratory: res.exploratory });
  return res;
}

// Options for the next RETENTION experiment when the model is deficient.
// Never a fixed "R² fails → run X %B" rule: each option is checked.
export function retentionPlan(session, settings, ctx) {
  const { eligible, fits, deficient, t0Proposed, spec, ref } = ctx;
  const bs = percentBSummary(eligible);
  const step = settings.retentionStep;
  const lowest = bs.values[0], highest = bs.values.at(-1);
  const options = [];
  const checks = [];
  const statement = 'Adding a point may IMPROVE OR WORSEN R². No existing point is removed or down-weighted; the fit is recomputed from all eligible points after the new run.';
  const { model } = runColumn(session, ref);
  const ins = runInstrument(session, ref).instrument;
  const pLimitCol = columnLimit(model, 'pressure');
  const pLimitIns = ins?.limits?.find(l => l.quantity === 'pressure');
  const phaseA = ref.conditions.phaseA;
  const lines = fits.results.filter(r => r.fit.ok && r.fit.slope < 0);
  const predictAt = B => lines.length ? Math.max(...lines.map(r => predictTR(r.fit, t0Proposed, B))) : null;
  const acq = usable(ref.conditions.acquisitionTime) ? Number(ref.conditions.acquisitionTime.value) : null;

  // A. extend below the lowest tested %B
  const lowB = lowest - step;
  if (lowB >= 0 && !bs.values.includes(lowB)) {
    const pred = predictAt(lowB);
    const exMin = ctx.exploratory?.candidates?.minimum?.B ?? null;
    const why = exMin !== null && exMin < lowest ? `The exploratory minimum (${exMin} %B) lies BELOW the lowest tested composition (${lowest} %B), i.e. it is an extrapolation; a measured point at ${lowB} %B brings that region inside the fitted range.`
      : `The fitted range is ${lowest}–${highest} %B; a point at ${lowB} %B extends the range by one ${step}-point step (Selectivity ED slide 16 ladder).`;
    const opt = { id: 'extend-low', action: `Inject the sample at ${lowB} %B (one ${step}-point step below the lowest tested ${lowest} %B)`, percentB: lowB, why, checks: [] };
    opt.checks.push(pred === null ? 'No fitted line to predict retention at this %B.' : `Exploratory prediction (from ALL fitted lines, including deficient ones): last peak ≈ ${pred.toFixed(2)} min at ${lowB} %B. ${pred > spec.value ? `This exceeds the ${spec.value} min runtime specification: the run is a MODELLING point, not a candidate method.` : 'Within the runtime specification.'}`);
    opt.checks.push(acq === null ? 'Acquisition time of the reference run is not recorded; set the acquisition time longer than the predicted last peak.' : pred !== null && pred > acq ? `The reference run acquired for ${acq.toFixed(1)} min; extend acquisition beyond ${pred.toFixed(1)} min or late peaks will be missed.` : `Reference acquisition ${acq.toFixed(1)} min covers the prediction.`);
    opt.checks.push(usable(phaseA) ? `Phase A is recorded as "${phaseA.value}"; lowering %B increases the proportion of phase A.` : 'Phase A is not recorded. Lowering %B increases the aqueous proportion; confirm phase A is the aqueous line before proposing this run.');
    opt.checks.push('Back-pressure at a lower %B cannot be predicted here: mobile-phase viscosity changes with composition and no viscosity data are supplied. Measure it.');
    const dsA = documentedLimitStatus(session, settings, ref);
    opt.checks.push(...dsA.checks);
    opt.checks.push('The marker must still be identifiable at the new composition (it does not move with %B, RETENTION Discovery Book §5.2), and peak identities in the new run must be assigned before the point can enter the fit.');
    opt.limitsUnverified = dsA.limitsUnverified;
    opt.needsInfo = !usable(phaseA);
    options.push(opt);
  } else if (lowB < 0) checks.push(`No lower step is possible: ${lowest} %B minus ${step} is below 0 %B.`);
  else checks.push(`${lowB} %B has already been tested.`);

  // B. repeat the point with the largest residual
  let worst = null;
  for (const d of deficient) for (const r of d.fit.residuals) if (!worst || Math.abs(r.residual) > Math.abs(worst.r.residual)) worst = { d, r };
  if (worst) {
    const dupe = bs.duplicates.find(x => x.percentB === worst.r.x);
    const wRun = eligible.find(e => e.runId === worst.r.runId)?.run || ref;  // by id: a label is an annotation and may be edited or duplicated
    const rl = repeatLimitCheck(session, settings, wRun, { measuredPressurePsi: measuredP(wRun), temperatureC: recordedT(wRun, settings) });
    options.push({ id: 'repeat-worst', percentB: worst.r.x,
      action: `Repeat the injection at ${worst.r.x} %B`,
      why: `The largest residual among the deficient lines is ${worst.r.residual.toFixed(4)} (log units) for ${worst.d.compound.name} at ${worst.r.x} %B (run "${worst.r.runLabel}"). ${dupe ? `That condition already has ${dupe.n} runs; a further repeat adds less information.` : 'A replicate tests whether that point is reproducible.'}`,
      checks: ['Same column, solvent, temperature and flow as the reference run.', ...rl.checks],
      limitsUnverified: rl.limitsUnverified, needsInfo: false });
  }
  // C. fill the widest gap
  let gap = null;
  for (let i = 1; i < bs.values.length; i++) { const g = bs.values[i] - bs.values[i - 1]; if (!gap || g > gap.g) gap = { g, lo: bs.values[i - 1], hi: bs.values[i] }; }
  if (gap && gap.g > step) {
    const mid = Math.round((gap.lo + gap.hi) / 2);
    const ds = documentedLimitStatus(session, settings, ref);
    options.push({ id: 'fill-gap', percentB: mid, action: `Inject at ${mid} %B to fill the ${gap.g}-point gap between ${gap.lo} and ${gap.hi} %B`,
      why: 'A point inside the range shows whether the line is straight between the tested compositions.',
      checks: [`${mid} %B lies between tested compositions, but it has NOT itself been run: mobile-phase viscosity changes with composition, so the back-pressure of this run is not known from the runs either side of it. Measure it.`, ...ds.checks],
      limitsUnverified: ds.limitsUnverified, needsInfo: false });
  }
  // preferred
  let preferred = null;
  const exMin = ctx.exploratory?.candidates?.minimum?.B ?? null;
  const extend = options.find(o => o.id === 'extend-low');
  if (extend && exMin !== null && exMin < lowest) preferred = extend;
  else preferred = options.find(o => o.id === 'fill-gap') || options.find(o => o.id === 'repeat-worst') || extend || null;
  return { existingPercentB: bs.values, duplicates: bs.duplicates, options, preferred, statement, checks,
    rule: 'Preferred option: extend below the lowest tested %B only when the exploratory minimum lies below it (an extrapolation); otherwise fill a gap wider than one step; otherwise replicate the worst-residual point.' };
}

// candidates.mjs — evaluate whole-number %B candidates against the runtime
// specification using every supplied compound line.
//
// Predicted tR(B) = t0 × (1 + 10^(a + b·B))  (RETENTION Discovery Book §8.4).
// The minimum whole-number %B is the smallest integer at which EVERY modelled
// compound is predicted to meet the last-peak specification (and every higher
// integer also does). Lowering %B lengthens the run, so the continuous
// threshold is rounded UP. Comparison uses unrounded predicted times.
import { compare } from '../rules.mjs';

export function predictTR(fit, t0, B) { return t0 * (1 + 10 ** (fit.intercept + fit.slope * B)); }

export function evaluateCandidates(lines, t0, spec, { from = 0, to = 100 } = {}) {
  // lines: [{compoundId, name, fit}] ; spec: {value, op}
  if (!lines.length) return { ok: false, reason: 'No compound line to evaluate.' };
  if (!(t0 > 0)) return { ok: false, reason: 't0 for the proposed run is not established.' };
  const rows = [];
  for (let B = from; B <= to; B++) {
    const preds = lines.map(l => ({ compoundId: l.compoundId, name: l.name, tR: predictTR(l.fit, t0, B) }));
    const top = preds.reduce((m, p) => p.tR > m.tR ? p : m);
    const cmp = compare(top.tR, spec.op, spec.value);
    rows.push({ B, preds, max: top.tR, controlling: top, feasible: !!cmp.pass });
  }
  // smallest B such that it and every higher candidate are feasible
  let minimum = null;
  for (let i = rows.length - 1; i >= 0; i--) { if (rows[i].feasible) minimum = rows[i]; else break; }
  // continuous threshold by bisection on max tR(B) − spec
  const f = B => Math.max(...lines.map(l => predictTR(l.fit, t0, B))) - spec.value;
  let threshold = null;
  if (f(from) > 0 && f(to) <= 0) { let lo = from, hi = to; for (let i = 0; i < 80; i++) { const mid = (lo + hi) / 2; if (f(mid) > 0) lo = mid; else hi = mid; } threshold = hi; }
  const range = l => ({ low: l.fit.xMin, high: l.fit.xMax });
  const position = minimum ? lines.map(l => ({ compoundId: l.compoundId, name: l.name, ...range(l),
    kind: minimum.B >= l.fit.xMin && minimum.B <= l.fit.xMax ? 'interpolation' : 'EXTRAPOLATION' })) : [];
  let explanation;
  if (!minimum) explanation = `No whole-number %B between ${from} and ${to} keeps every modelled compound ${spec.op} ${spec.value} min.`;
  else if (minimum.B === from) explanation = `Every candidate down to ${from} %B is predicted within the limit; the minimum is not bounded by the runtime specification in this range.`;
  else explanation = `Continuous threshold ${threshold === null ? 'n/a' : threshold.toFixed(4)} %B, rounded UP to ${minimum.B} %B because a lower %B lengthens the run. At ${minimum.B} %B the predicted latest elution is ${minimum.controlling.name} at ${minimum.max.toFixed(3)} min; at ${minimum.B - 1} %B it would be ${rows[minimum.B - 1 - from].max.toFixed(3)} min.`;
  return { ok: true, rows, minimum, threshold, position, explanation,
    controlling: minimum ? minimum.controlling : null,
    anyExtrapolation: position.some(p => p.kind === 'EXTRAPOLATION') };
}

// Intermediate %B: among candidates from the minimum up to the highest
// fitted %B, the composition that maximises the smallest predicted adjacent
// selectivity α between modelled compounds (Selectivity ED slides 16–22:
// "find the sweet spot"). Peak widths are not modelled, so this ranks spacing,
// not resolution. Needs at least two modelled compounds.
export function intermediateB(lines, t0, minimumB, upperB) {
  if (lines.length < 2) return { ok: false, reason: 'At least two modelled compounds are needed to compare spacing.' };
  if (minimumB === null || minimumB === undefined) return { ok: false, reason: 'No minimum %B to start from.' };
  let best = null;
  const table = [];
  for (let B = minimumB; B <= upperB; B++) {
    const ks = lines.map(l => ({ name: l.name, k: 10 ** (l.fit.intercept + l.fit.slope * B) })).sort((a, b) => a.k - b.k);
    let minA = Infinity, pair = null;
    for (let i = 1; i < ks.length; i++) { const a = ks[i].k / ks[i - 1].k; if (a < minA) { minA = a; pair = [ks[i - 1].name, ks[i].name]; } }
    const lastTR = t0 * (1 + ks.at(-1).k);
    table.push({ B, minAlpha: minA, pair, lastTR });
    if (!best || minA > best.minAlpha + 1e-12 || (Math.abs(minA - best.minAlpha) <= 1e-12 && B > best.B)) best = { B, minAlpha: minA, pair, lastTR };
  }
  return { ok: true, best, table,
    note: 'Predicted from the fitted lines: ranks the smallest adjacent α (spacing only; widths are not modelled). Predicted order can be wrong where lines cross. Verify by injection.' };
}

// eligibility.mjs — which runs may be pooled in a retention fit, and why.
//
// A run joins the fit only if the user ticked "include in retention fit" AND it
// passes every check below against the fit reference run. Unknown values never
// establish comparability: a missing temperature, column or solvent cannot be
// shown to be the same as anything, including another missing value.
import { usable, knownValue, sourceLabel } from '../data-model/conditions.mjs';
import { chronological, chronologyStatus } from '../data-model/session.mjs';
import { runColumn, runInstrument, organicOf, percentBOf, modeOf, isBlank, effectiveTemperature, t0Of, flowOf } from '../data-model/derive.mjs';
import { num } from '../rules.mjs';
import { sampleCompare } from '../data-model/comparability.mjs';

export function fitReference(session, settings) {
  const flagged = session.runs.filter(r => r.flags.fit && !isBlank(r));
  if (!flagged.length) return null;
  if (settings.fitReferenceRunId) { const r = flagged.find(x => x.id === settings.fitReferenceRunId); if (r) return r; }
  return chronological(session, flagged).at(-1);
}

function why(cond, what) {
  if (!knownValue(cond)) return `${what} is not recorded`;
  if (!cond.confirmed) return `${what} (${cond.value}) comes from ${sourceLabel(cond)} — confirm it to use it`;
  return null;
}

export function requiredKnowns(session, settings, run) {
  const missing = [];
  const col = runColumn(session, run);
  if (!col.column) missing.push('physical column not associated (Equipment stage)');
  else if (!col.confirmed) missing.push(`column association "${col.column.label}" is not confirmed (${col.source})`);
  const o = why(run.conditions.organic, 'organic solvent'); if (o) missing.push(o);
  if(/^(mix\b|acn\s*\+\s*meoh|meoh\s*\+\s*acn)/i.test(organicOf(run)||''))missing.push('Mix (ACN + MeOH) is recorded as a mixed solvent. This tool has no defined Mix retention/nomogram model, so it does not issue a minimum %B for Mix.');
  const m = why(run.conditions.mode, 'elution mode'); if (m) missing.push(m);
  else if (modeOf(run) !== 'ISO') missing.push(`elution mode is ${modeOf(run)}; the log K vs %B model applies to isocratic runs`);
  const b = why(run.conditions.percentB, '%B'); if (b) missing.push(b);
  const T = effectiveTemperature(run, settings); if (!T.known) missing.push(`column temperature unknown: ${T.reason}`);
  return { missing, temperature: T, column: col };
}

// Compare a run with the reference. Returns {comparable, reasons[], notes[]}.
export function lineageCompare(session, settings, run, ref) {
  const reasons = [], notes = [];
  const sample = sampleCompare(session, run, ref);
  reasons.push(...sample.reasons); notes.push(...sample.notes);
  const a = requiredKnowns(session, settings, run), b = run === ref ? a : requiredKnowns(session, settings, ref);
  if (a.missing.length) reasons.push(...a.missing);
  if (run !== ref && b.missing.length) reasons.push(`the fit reference run "${ref.label}" lacks: ${b.missing.join('; ')}`);
  if (reasons.length) return { comparable: false, reasons, notes };
  if (run !== ref) {
    if (a.column.column.id !== b.column.column.id) reasons.push(`different physical column ("${a.column.column.label}" vs "${b.column.column.label}")`);
    if (organicOf(run) !== organicOf(ref)) reasons.push(`different organic solvent (${organicOf(run)} vs ${organicOf(ref)})`);
    const dT = Math.abs(a.temperature.value - b.temperature.value);
    if (dT > settings.tempMatchTolerance) reasons.push(`temperature differs by ${dT.toFixed(2)} °C (${a.temperature.value.toFixed(2)} vs ${b.temperature.value.toFixed(2)} °C), more than the ${settings.tempMatchTolerance} °C comparability tolerance`);
    else notes.push(`temperature ${a.temperature.value.toFixed(2)} vs reference ${b.temperature.value.toFixed(2)} °C (within ${settings.tempMatchTolerance} °C)`);
  }
  for (const [k, label] of [['pH', 'pH'], ['additiveName', 'additive'], ['additiveConc', 'additive concentration'], ['phaseA', 'phase A']]) {
    const x = run.conditions[k], y = ref.conditions[k];
    const kx = usable(x), ky = usable(y);
    if (kx && ky && String(x.value) !== String(y.value)) reasons.push(`different ${label} (${x.value} vs ${y.value})`);
    else if (kx !== ky && run !== ref) reasons.push(`${label} is recorded on only one of the two runs, so they cannot be shown to match`);
    else if (!kx && !ky) notes.push(`${label} not recorded (comparability on ${label} is unverified)`);
  }
  if (run !== ref) {
    const fa = flowOf(run), fb = flowOf(ref);
    if (fa !== null && fb !== null && fa !== fb) notes.push(`flow differs (${fa} vs ${fb} mL/min): K is unchanged by flow at constant chemistry (RETENTION Discovery Book §6), and t0 is taken per run`);
    const ia = runInstrument(session, run).instrument, ib = runInstrument(session, ref).instrument;
    if (ia && ib && ia.id !== ib.id) notes.push(`different instrument ("${ia.label}" vs "${ib.label}"): extra-column volume can differ; t0 is taken per run`);
  }
  return { comparable: reasons.length === 0, reasons, notes };
}

export function fitEligibility(session, settings) {
  const ref = fitReference(session, settings);
  const flagged = session.runs.filter(r => r.flags.fit && !isBlank(r));
  const chron = chronologyStatus(session, flagged);
  const out = { reference: ref, runs: [], chronology: chron,
    // The reference affects only comparability and t0, not the line itself,
    // but it must not be chosen by the order files were selected in.
    referenceBasis: settings.fitReferenceRunId && ref?.id === settings.fitReferenceRunId ? 'selected explicitly by the user'
      : chron.ok ? `last run by ${chron.basis}` : `last run in an UNESTABLISHED order (${chron.reason}) — select the reference explicitly`,
    referenceUncertain: !(settings.fitReferenceRunId && ref?.id === settings.fitReferenceRunId) && !chron.ok };
  for (const run of chronological(session, session.runs.filter(r => r.flags.fit))) {
    const reasons = [], notes = [];
    if (isBlank(run)) reasons.push('recorded as a blank — no analyte peaks expected');
    if (!run.measured.peaks.length) reasons.push('no peaks in the peak table');
    const t0 = t0Of(session, run, settings);
    if (!t0.ok) reasons.push(`t0 not established: ${t0.text}`);
    let lin = { comparable: false, reasons: [], notes: [] };
    if (ref) { lin = lineageCompare(session, settings, run, ref); reasons.push(...lin.reasons); notes.push(...lin.notes); }
    out.runs.push({ run, runId: run.id, label: run.label, eligible: reasons.length === 0, reasons, notes, t0,
      lineageOk: !!ref && lin.comparable, blank: isBlank(run), hasPeaks: run.measured.peaks.length > 0,
      percentB: percentBOf(run), temperature: effectiveTemperature(run, settings), isReference: run === ref });
  }
  return out;
}

// Distinct %B values among eligible runs and replicated conditions.
export function percentBSummary(eligibleRuns) {
  const counts = new Map();
  for (const e of eligibleRuns) counts.set(e.percentB, (counts.get(e.percentB) || 0) + 1);
  const values = [...counts.keys()].sort((a, b) => a - b);
  return { values, duplicates: [...counts].filter(([, n]) => n > 1).map(([b, n]) => ({ percentB: b, n })) };
}
export const numOrNull = num;

// exploratory.mjs — POSITION HYPOTHESES (front- and back-aligned elution
// positions) for runs whose peaks have no confirmed identities.
//
// These are exploratory calculations only. A position is not a compound; equal
// peak counts do not establish identity; monotonic behaviour is a consistency
// check, not proof. Two hypotheses are shown because they are easy to state —
// they are NOT an exhaustive set of chemically possible mappings. Results are
// never issued as a next-run method.
import { retentionFactor, linearFit } from '../rules.mjs';
import { evaluateCandidates } from './candidates.mjs';
import { relevantPeaks } from '../data-model/derive.mjs';

export const EXPLORATORY_LABEL = 'EXPLORATORY — position hypothesis, not compound identities. Not exhaustive. Not issued as a method.';

export function positionHypotheses(session, settings, eligibilityRuns, t0Proposed, spec) {
  // runs that pass everything except identities
  const usableRuns = eligibilityRuns.filter(e => e.t0.ok && e.percentB !== null && e.lineageOk && !e.blank && e.hasPeaks);
  if (usableRuns.length < 2) return { ok: false, reason: 'Fewer than two comparable runs with an established t0.' };
  const series = { front: new Map(), back: new Map() };
  for (const e of usableRuns) {
    const t0 = e.t0.t0;
    const retained = relevantPeaks(e.run).filter(p => p.tR > t0 + 1e-9);
    retained.forEach((p, i) => {
      const k = retentionFactor(p.tR, t0); if (!k.ok) return;
      const pt = { runLabel: e.label, x: e.percentB, y: k.logK, tR: p.tR, k: k.k };
      const f = i + 1, b = -(retained.length - i);
      if (!series.front.has(f)) series.front.set(f, []); series.front.get(f).push(pt);
      if (!series.back.has(b)) series.back.set(b, []); series.back.get(b).push(pt);
    });
  }
  const out = {};
  for (const [name, map] of Object.entries(series)) {
    const lines = [], skipped = [];
    let violations = 0;
    for (const [pos, pts] of map) {
      const sorted = [...pts].sort((a, b) => a.x - b.x);
      for (let i = 1; i < sorted.length; i++) if (sorted[i].x > sorted[i - 1].x && sorted[i].y >= sorted[i - 1].y) violations++;
      const fit = linearFit(pts);
      if (!fit.ok || fit.n < settings.minFitPoints) { skipped.push({ pos, n: pts.length }); continue; }
      lines.push({ compoundId: `${name}:${pos}`, name: `${name === 'front' ? 'front' : 'back'} position ${pos}`, fit, pts });
    }
    const cand = lines.length && t0Proposed > 0 ? evaluateCandidates(lines, t0Proposed, spec) : null;
    out[name] = { lines, skipped, violations, candidates: cand };
  }
  return { ok: true, label: EXPLORATORY_LABEL, usedRuns: usableRuns.map(e => e.label), ...out,
    note: 'Monotonicity violations count how often a position\'s log K does not fall as %B rises — a consistency check only (RETENTION Discovery Book §8.2), not an identification.' };
}

// fit.mjs — one log K vs %B line PER IDENTIFIED COMPOUND.
//
// Points come only from CONFIRMED peak-to-compound assignments in eligible,
// comparable runs. Co-eluted peaks and peaks with K ≤ 0 are excluded with a
// reason. No point is ever removed to improve a fit: every eligible point is
// used. log means log10.
import { retentionFactor, linearFit, compare } from '../rules.mjs';
import { confirmedPeakOf, peakStatus } from '../alignment/correspondence.mjs';
import { R2_POLICIES } from '../presets/bps2032.mjs';
import { peakExcluded } from '../data-model/peak-filter.mjs';

export function activeR2Policy(settings) {
  const p = settings.r2Policy || { mode: 'none' };
  if (p.mode === 'none') return { mode: 'none', target: null, op: '>=', label: R2_POLICIES.none.label, judged: false };
  if (p.mode === 'project') return { mode: 'project', target: 0.995, op: '>=', decimals:3, label: R2_POLICIES.project.label, judged: true };
  if (p.mode === 'custom' && Number.isFinite(p.target)) return { mode: 'custom', target: p.target, op: p.op || '>=', label: `R² ${p.op || '>='} ${p.target} — user criterion`, judged: true };
  return { mode: 'none', target: null, op: '>=', label: 'Custom target not set — no criterion applied', judged: false };
}
// User-confirmed project convention (2026-10-12), not a course-wide rule.
// Measured/fit R² remains unmodified; only the acceptance value is rounded.
export function projectR2(r2) {return Number.isFinite(r2)?Math.round((r2+Number.EPSILON)*1000)/1000:null;}

export function fitCompounds(session, settings, eligibility) {
  const eligible = eligibility.runs.filter(e => e.eligible);
  const policy = activeR2Policy(settings);
  const analytes = session.compounds.filter(c => c.role !== 'marker');
  const results = [];
  for (const c of analytes) {
    const points = [], excluded = [], missingIn = [];
    for (const e of eligible) {
      const pk = confirmedPeakOf(session, e.run, c.id);
      if (!pk) { missingIn.push(e.label); continue; }
      const note = e.run.peakNotes?.[pk.no] || {};
      if (note.coeluted) { excluded.push({ runLabel: e.label, percentB: e.percentB, reason: 'peak marked as co-eluted' }); continue; }
      if (peakExcluded(e.run,pk)) { excluded.push({ runLabel: e.label, percentB: e.percentB, reason: `peak excluded by user annotation or height filter: ${note.reason || 'selected height threshold'}` }); continue; }
      const k = retentionFactor(pk.tR, e.t0.t0);
      if (!k.ok) { excluded.push({ runLabel: e.label, percentB: e.percentB, reason: k.reason }); continue; }
      points.push({ runId: e.runId, runLabel: e.label, x: e.percentB, y: k.logK, tR: pk.tR, t0: e.t0.t0, k: k.k, peakNo: pk.no, proxy: !!e.t0.proxy, estimate: !!e.t0.estimate });
    }
    const fit = linearFit(points);
    const reasons = [];
    let quality = { judged: false, pass: null, statement: '' };
    if (!fit.ok) reasons.push(fit.reason);
    else {
      if (fit.n < settings.minFitPoints) reasons.push(`${fit.n} point(s); the minimum for a judged fit is ${settings.minFitPoints} (with two points R² is always 1)`);
      if (!(fit.slope < 0)) reasons.push(`slope ${fit.slope.toFixed(5)} is not negative; the course relationship has log K FALLING as %B rises (RETENTION Discovery Book §8.2), so this line is not a usable retention model — check the assignments`);
      if (policy.judged) {
        if (fit.r2 === null) { quality = { judged: true, pass: false, statement: 'R² undefined (no variation in log K).' }; reasons.push(quality.statement); }
        else {
          const compared=policy.mode==='project'?projectR2(fit.r2):fit.r2,cmp = compare(compared, policy.op, policy.target);
          quality = { judged: true, pass: cmp.pass, statement: `R² = ${fit.r2.toFixed(6)} ${cmp.pass ? 'meets' : 'does NOT meet'} ${cmp.opLabel} ${policy.target} (${policy.mode==='project'?`project acceptance value rounded to 3 decimals: ${compared.toFixed(3)}; raw R²: ${fit.r2}`:`compared unrounded: ${fit.r2}`})` };
          if (!cmp.pass) reasons.push(quality.statement);
        }
      } else quality = { judged: false, pass: null, statement: `R² = ${fit.r2 === null ? 'undefined' : fit.r2.toFixed(6)} (no fit-quality criterion selected; not judged)` };
    }
    const proxy = points.some(p => p.proxy), estimate = points.some(p => p.estimate);
    const adequate = fit.ok && reasons.length === 0;
    results.push({ compound: c, points, excluded, missingIn, fit, quality, reasons, adequate, proxy, estimate,
      // S and a in the course sign convention: log K = a − S × %B
      course: fit.ok ? { a: fit.intercept, S: -fit.slope } : null });
  }
  const modelled = results.filter(r => r.adequate);
  // Coverage of the DEFINED analytes is not coverage of the SAMPLE. A peak
  // that carries no confirmed identity is a component of the sample that is
  // not in the compound list, so a line for every defined compound is still
  // not a whole-sample model. Peaks marked as artefacts or as co-elutions are
  // accounted for with a reason and are listed separately.
  const unattributed = [];
  for (const e of eligible) for (const p of peakStatus(session, e.run)) {
    if (p.state === 'unmatched' || p.state === 'proposed' || p.state === 'ambiguous')
      unattributed.push({ runId: e.runId, runLabel: e.label, percentB: e.percentB, peakNo: p.no, tR: p.tR, state: p.state });
  }
  const definedComplete = analytes.length > 0 && modelled.length === analytes.length;
  const coverage = { expected: analytes.length || null, adequate: modelled.length, fitted: results.filter(r => r.fit.ok).length,
    definedComplete, unattributed,
    unattributedRuns: [...new Set(unattributed.map(u => u.runLabel))],
    // "complete" is used by the decision layer as "a whole-sample model": it
    // requires both every defined analyte modelled AND no unidentified peak.
    complete: definedComplete && unattributed.length === 0,
    sampleReason: unattributed.length === 0 ? null
      : `${unattributed.length} peak(s) in ${[...new Set(unattributed.map(u => u.runLabel))].length} eligible run(s) carry no confirmed identity (${unattributed.slice(0, 6).map(u => `${u.runLabel} peak ${u.peakNo} at ${u.tR.toFixed(2)} min, ${u.state}`).join('; ')}${unattributed.length > 6 ? '; …' : ''}). Each is a component of the sample that is not in the compound list, so a line for every DEFINED compound is not a whole-sample model. Either assign and confirm these peaks, define the missing analytes, or mark each peak as an artefact with a reason.`,
    missing: results.filter(r => !r.adequate).map(r => r.compound.name) };
  return { policy, results, coverage, anyProxy: results.some(r => r.proxy), eligibleCount: eligible.length };
}

// Pre-experiment planning. A handoff refers to a freshly recomputed model,
// never to stored predictions or a merged experiment library.
import { predictTR } from './candidates.mjs';
import { compare } from '../rules.mjs';
import { activeR2Policy,projectR2 } from './fit.mjs';
import { sha256 } from '../data-model/ids.mjs';

export function lastPeakCalculation(input,settings) {
  const {t0,slope,intercept,r2}=input||{}, spec=settings.specs.lastPeak,policy=activeR2Policy(settings);
  if(settings.r2Policy?.mode==='custom'&&!Number.isFinite(settings.r2Policy.target))return {ok:false,ready:false,reason:'Set the custom R² target in Model setup, or select an explicit report-only/project policy.'};
  if(![t0,slope,intercept,r2,spec.value].every(Number.isFinite)||!(t0>0)||!(slope<0)||!(spec.value>t0)||r2<0||r2>1)
    return {ok:false,ready:false,reason:'Enter t0 > 0 min, a negative slope, intercept, R² from 0 to 1, and a run-time limit greater than t0. Blank inputs are not zero.'};
  const k=(spec.value-t0)/t0,logK=Math.log10(k),continuous=(logK-intercept)/slope;
  let B=Math.max(0,Math.ceil(continuous));
  while(B<=100&&!compare(predictTR({intercept,slope},t0,B),spec.op,spec.value).pass)B++;
  const feasible=B<=100,pass=!policy.judged||compare(policy.mode==='project'?projectR2(r2):r2,policy.op,policy.target).pass;
  return {ok:true,ready:feasible&&pass,k,logK,continuous,B:feasible?B:null,
    predictedLast:feasible?predictTR({intercept,slope},t0,B):null,previousLast:B>0?predictTR({intercept,slope},t0,B-1):null,
    r2Pass:pass,policy,reason:(!feasible?'No feasible whole-number %B from 0 to 100.':!pass?'R² fails the selected criterion. Continue Retention and investigate the fit before using this calculation.':'Last-peak model calculation.')+' It does not establish an all-compound minimum or validate a method.'};
}
export function modelFingerprint(r) {
  if(!r?.issued?.candidates?.minimum)return null;
  const ref=r.eligibility.reference;
  return sha256(JSON.stringify({minimum:r.issued.candidates.minimum.B,spec:r.steps.lastPeakSpec,t0:r.steps.t0Proposed,
    fits:r.steps.fits,reference:{id:ref?.id,conditions:ref?.conditions,assoc:ref?.assoc,marker:ref?.marker,
      measuredHash:sha256(JSON.stringify(ref?.measured)),sourceHash:ref?.raw?.sha256},policy:r.fits?.policy}));
}
export function automaticModelQuality(r){const fits=r?.fits?.results?.filter(x=>x.adequate)||[];return !!r?.issued?.candidates?.minimum&&fits.length>0&&fits.every(x=>projectR2(x.fit.r2)!==null&&projectR2(x.fit.r2)>=.995&&new Set(x.points.map(p=>p.x)).size>=3);}
export function selectivityPlanning(session,reference=null,own=null) {
  const p=session.settings.compositionPlan||{};
