  rows:Object.fromEntries(Object.entries(c.rows&&typeof c.rows==='object'?c.rows:{}).map(([id,r])=>[id,{t0:number(r?.t0),t0Basis:text(r?.t0Basis),exclude:r?.exclude===true,reason:text(r?.reason)}]))};
}
function groupOf(s,r){
