// rules.mjs — dataset-independent calculations and comparison rules.
//
// Nothing in this file knows about any particular dataset, instrument, column,
// file-naming convention or teaching preset. Every function is pure: it takes
// plain values and returns plain values. Functions that can fail return a
// structured result {ok:false, reason} instead of inventing a number.

export const LOG_CONVENTION = 'log means log10 (base-10 logarithm) throughout. K = 10^(log K).';

// ---------------------------------------------------------------- numbers
export function num(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const s = String(value).trim();
  if (s === '') return null;
  const n = Number(s.replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
}
export function positive(value) { const n = num(value); return n !== null && n > 0 ? n : null; }
export const isKnown = v => !(v === null || v === undefined || v === '' || (typeof v === 'number' && !Number.isFinite(v)));

// ---------------------------------------------------------------- comparisons
// Specifications carry their own comparison operator so the operator is shown
// and applied, never assumed. Comparison is ALWAYS on the unrounded value.
export const OPERATORS = {
  '<': { label: '<', test: (a, b) => a < b, words: 'strictly less than' },
  '<=': { label: '≤', test: (a, b) => a <= b, words: 'less than or equal to' },
  '>': { label: '>', test: (a, b) => a > b, words: 'strictly greater than' },
  '>=': { label: '≥', test: (a, b) => a >= b, words: 'greater than or equal to' },
  '=': { label: '=', test: (a, b) => a === b, words: 'equal to' },
};
export function compare(value, op, target) {
  const v = num(value), t = num(target);
  const o = OPERATORS[op];
  if (!o) return { known: false, pass: null, reason: `Unknown comparison operator "${op}".` };
  if (v === null) return { known: false, pass: null, reason: 'Value not available.' };
  if (t === null) return { known: false, pass: null, reason: 'Target not set.' };
  return { known: true, pass: o.test(v, t), value: v, target: t, op, opLabel: o.label,
    statement: `${v} ${o.test(v, t) ? 'meets' : 'does not meet'} ${o.label} ${t} (unrounded comparison)` };
}

// A specification the user has edited is checked before it is applied. An
// impossible specification is refused with the offending field named: applying
// it would produce a decision that looks authoritative and means nothing.
// What each specification admits (the quantity, not a course rule):
//   peakCount  a whole number ≥ 0 of peaks
//   lastPeak   a retention time > 0 min
//   minRs      a resolution ≥ 0
//   pressure   a back-pressure > 0 psi
export const SPEC_DOMAINS = {
  peakCount: { label: 'peak count', unit: '', test: v => Number.isInteger(v) && v >= 0, admits: 'a whole number of peaks, 0 or more' },
  lastPeak: { label: 'latest relevant peak', unit: 'min', test: v => v > 0, admits: 'a retention time greater than 0 min' },
  minRs: { label: 'lowest adjacent-pair resolution', unit: '', test: v => v >= 0, admits: 'a resolution of 0 or more' },
  pressure: { label: 'back-pressure', unit: 'psi', test: v => v > 0, admits: 'a back-pressure greater than 0 psi' },
};
export function validateSpecs(specs) {
  const problems = [];
  for (const [key, d] of Object.entries(SPEC_DOMAINS)) {
    const sp = specs?.[key];
    if (!sp || typeof sp !== 'object') { problems.push({ key, text: `The ${d.label} specification is not set.` }); continue; }
    if (!OPERATORS[sp.op]) { problems.push({ key, text: `The ${d.label} specification uses an unknown comparison operator "${sp.op === undefined ? 'none' : sp.op}". Admissible operators: ${Object.keys(OPERATORS).map(o => OPERATORS[o].label).join(' ')}.` }); }
    const v = num(sp.value);
    if (v === null) { problems.push({ key, text: `The ${d.label} specification value "${sp.value === undefined || sp.value === null ? 'empty' : sp.value}" is not a number. It admits ${d.admits}.` }); continue; }
    if (!d.test(v)) problems.push({ key, text: `The ${d.label} specification is ${v}${d.unit ? ' ' + d.unit : ''}, which is outside what the quantity admits (${d.admits}).` });
  }
  return { ok: problems.length === 0, problems };
}

// Pressure units. A limit recorded in bar or MPa is NOT a number of psi, and
// comparing it as one would silently misjudge the limit by an order of
// magnitude. An unrecognised unit is refused rather than assumed.
export const PRESSURE_UNITS = { psi: 1, bar: 14.503773773, mpa: 145.03773773, kpa: 0.14503773773 };
export function toPsi(value, unit) {
  const v = num(value);
  if (v === null) return { ok: false, reason: 'the value is not a number' };
  const key = String(unit ?? '').trim().toLowerCase();
  if (key === '') return { ok: false, reason: 'no unit is recorded with the value, so it cannot be compared with a pressure in psi' };
  const f = PRESSURE_UNITS[key];
  if (!f) return { ok: false, reason: `the unit "${unit}" is not a pressure unit this tool recognises (psi, bar, MPa, kPa)` };
  return { ok: true, psi: v * f, unit: key, factor: f };
}

// The tool's own configurable policies. They are not course rules, so the one
// thing the tool must do is refuse a setting that cannot mean anything, rather
// than produce a confident decision from it.
export const POLICY_DOMAINS = {
  runtimeApproachingFraction: { label: 'run-time "approaching" fraction', admits: 'a fraction strictly between 0 and 1 (0.75 by default)', test: v => Number.isFinite(v) && v > 0 && v < 1, optional: true },
  tempStabilityTolerance: { label: 'oven stability tolerance', unit: '°C', admits: 'a positive number of °C', test: v => Number.isFinite(v) && v > 0 },
  tempMatchTolerance: { label: 'temperature comparability tolerance', unit: '°C', admits: 'a positive number of °C', test: v => Number.isFinite(v) && v > 0 },
  retentionStep: { label: '%B ladder step', unit: '%', admits: 'a positive number of percentage points', test: v => Number.isFinite(v) && v > 0 },
  minFitPoints: { label: 'minimum points per compound fit', admits: 'a whole number of 2 or more (with two points R² is always 1)', test: v => Number.isInteger(v) && v >= 2 },
  ovenMinReadings: { label: 'minimum oven readings inside the analysed interval', admits: 'a whole number of 2 or more', test: v => Number.isInteger(v) && v >= 2, optional: true },
  ovenMaxGapFraction: { label: 'largest admissible gap between oven readings', admits: 'a fraction strictly between 0 and 1 of the analysed interval', test: v => Number.isFinite(v) && v > 0 && v < 1, optional: true },
};
export function validatePolicies(settings) {
  const problems = [];
  for (const [key, d] of Object.entries(POLICY_DOMAINS)) {
    const v = settings?.[key];
    if (v === undefined || v === null) { if (!d.optional) problems.push({ key, text: `The ${d.label} is not set. It admits ${d.admits}.` }); continue; }
    if (!d.test(typeof v === 'string' ? num(v) : v)) problems.push({ key, text: `The ${d.label} is ${JSON.stringify(v)}, which cannot be applied: it admits ${d.admits}.` });
  }
  const steps = settings?.temperatureSteps;
  if (!Array.isArray(steps) || steps.length !== 2) problems.push({ key: 'temperatureSteps', text: `The temperature steps must be exactly two values; ${Array.isArray(steps) ? `${steps.length} were given` : 'none were given'}.` });
  else if (!steps.every(x => Number.isFinite(num(x)))) problems.push({ key: 'temperatureSteps', text: `The temperature steps ${JSON.stringify(steps)} are not both numbers.` });
  else if (!(num(steps[0]) < num(steps[1]))) problems.push({ key: 'temperatureSteps', text: `The temperature steps ${steps[0]} and ${steps[1]} °C are not in increasing order with two distinct values, so "temperature 1" and "temperature 2" would not be two different experiments.` });
  const sol = settings?.availableSolvents;
  if (!Array.isArray(sol) || !sol.length) problems.push({ key: 'availableSolvents', text: 'No organic solvent is listed as available, so no solvent step can be planned.' });
  return { ok: problems.length === 0, problems };
}

// ---------------------------------------------------------------- retention
// K = (tR − t0) / t0. Both in minutes; K is dimensionless.
export function retentionFactor(tR, t0) {
  const t = num(tR), z = positive(t0);
  if (t === null) return { ok: false, reason: 'Retention time missing.' };
  if (z === null) return { ok: false, reason: 't0 is not established (missing or not positive).' };
  const k = (t - z) / z;
  if (!(k > 0)) return { ok: false, k, reason: `K = (${t} − ${z}) / ${z} = ${k.toFixed(4)} is not positive; log K is undefined. The peak elutes at or before t0.` };
  return { ok: true, k, logK: Math.log10(k) };
}
export const tRFromK = (k, t0) => t0 * (1 + k);

// Ordinary least squares y = a + b x, with R², residuals and fitted range.
export function linearFit(points) {
  const pts = points.filter(p => Number.isFinite(p.x) && Number.isFinite(p.y));
  const n = pts.length;
  const xs = [...new Set(pts.map(p => p.x))];
  if (n < 2 || xs.length < 2) return { ok: false, n, reason: `A straight line needs at least two distinct %B values; ${xs.length} available.` };
  const mx = pts.reduce((s, p) => s + p.x, 0) / n, my = pts.reduce((s, p) => s + p.y, 0) / n;
  let sxx = 0, sxy = 0, syy = 0;
  for (const p of pts) { sxx += (p.x - mx) ** 2; sxy += (p.x - mx) * (p.y - my); syy += (p.y - my) ** 2; }
  const b = sxy / sxx, a = my - b * mx;
  const residuals = pts.map(p => ({ ...p, fitted: a + b * p.x, residual: p.y - (a + b * p.x) }));
  const sse = residuals.reduce((s, r) => s + r.residual ** 2, 0);
  const r2 = syy === 0 ? null : 1 - sse / syy;
  return { ok: true, n, distinctX: xs.length, intercept: a, slope: b, r2, sse,
    rmse: Math.sqrt(sse / n), residuals,
    xMin: Math.min(...xs), xMax: Math.max(...xs),
    maxAbsResidual: Math.max(...residuals.map(r => Math.abs(r.residual))) };
}

// ---------------------------------------------------------------- resolution
// RESOLUTION Discovery Book §4.2: Rs = 2 (tR2 − tR1) / (Wb1 + Wb2)  (base widths)
// RESOLUTION Discovery Book §4.4: Rs = 1.18 (tR2 − tR1) / (Wh1 + Wh2) (half-height widths, USP ⟨621⟩)
// Plate-derived: for an ideal (Gaussian) peak N = 16 (tR / Wb)², so Wb = 4 tR / √N.
// This is an IDEAL-SHAPE assumption: Wb = 1.7 Wh stops holding once a peak tails
// (RESOLUTION Discovery Book §3.3).
export const RS_BASES = {
  'base-width': { label: 'Base width (Wb), Rs = 2Δt / (Wb1 + Wb2)', needs: 'widthBase', source: 'RESOLUTION Discovery Book §4.2' },
  'half-width': { label: 'Half-height width (Wh), Rs = 1.18Δt / (Wh1 + Wh2)', needs: 'widthHalf', source: 'RESOLUTION Discovery Book §4.4 (USP ⟨621⟩ form)' },
  'plate-gaussian': { label: 'Gaussian-equivalent base width from exported plate number, Wb = 4tR/√N, then Rs = 2Δt/(Wb1+Wb2)', needs: 'plates', source: 'RESOLUTION Discovery Book §4.2 with N = 16(tR/Wb)²; ideal peak shape assumed' },
  'exported': { label: 'Instrument-exported resolution (as reported for each peak against the previous peak)', needs: 'exportedRs', source: 'Instrument export; RESOLUTION Discovery Book §3.4 states the software used in this unit calculates Rs from base width' },
};
export function pairRs(p, q, basis) {
  const dt = num(q.tR) - num(p.tR);
  if (!(dt > 0)) return { ok: false, reason: 'Retention times are not increasing.' };
  if (basis === 'base-width') {
    const w1 = positive(p.widthBase), w2 = positive(q.widthBase);
    if (w1 === null || w2 === null) return { ok: false, reason: 'Base width missing for one of the two peaks.' };
    return { ok: true, rs: 2 * dt / (w1 + w2), formula: `2 × ${dt.toFixed(4)} / (${w1} + ${w2})` };
  }
  if (basis === 'half-width') {
    const w1 = positive(p.widthHalf), w2 = positive(q.widthHalf);
    if (w1 === null || w2 === null) return { ok: false, reason: 'Half-height width missing for one of the two peaks.' };
    return { ok: true, rs: 1.18 * dt / (w1 + w2), formula: `1.18 × ${dt.toFixed(4)} / (${w1} + ${w2})` };
  }
  if (basis === 'plate-gaussian') {
    const n1 = positive(p.plates), n2 = positive(q.plates);
    if (n1 === null || n2 === null) return { ok: false, reason: 'Plate number missing or zero for one of the two peaks (an exported 0 means "not calculated", not zero).' };
    const w1 = 4 * num(p.tR) / Math.sqrt(n1), w2 = 4 * num(q.tR) / Math.sqrt(n2);
    return { ok: true, rs: 2 * dt / (w1 + w2), formula: `2 × ${dt.toFixed(4)} / (${w1.toFixed(4)} + ${w2.toFixed(4)}) [Wb = 4tR/√N]` };
  }
  if (basis === 'exported') {
    if(p.originalIndex!==undefined && q.originalIndex!==p.originalIndex+1) return {ok:false,reason:'Filtering made a new adjacent pair. Exported Rs belongs to the original previous peak; supply widths or use a documented recalculation basis.'};
    const r = positive(q.exportedRs);
    if (r === null) return { ok: false, reason: 'No exported resolution for the later peak (an exported 0 means "not calculated").' };
    return { ok: true, rs: r, formula: 'exported value' };
  }
  return { ok: false, reason: `Unknown resolution basis "${basis}".` };
}
// All adjacent pairs; the chromatogram's resolution is the LOWEST adjacent pair
// (RESOLUTION Discovery Book §5.5). The closest pair is not assumed to be the worst.
export function adjacentResolutions(peaks, basis) {
  const pairs = [];
  for (let i = 1; i < peaks.length; i++) {
    const r = pairRs(peaks[i - 1], peaks[i], basis);
    pairs.push({ from: peaks[i - 1].no, to: peaks[i].no, tR1: peaks[i - 1].tR, tR2: peaks[i].tR, gap: num(peaks[i].tR) - num(peaks[i - 1].tR), ...r });
  }
  const missing = pairs.filter(p => !p.ok);
  const valid = pairs.filter(p => p.ok);
  let limiting = null;
  if (pairs.length && !missing.length) limiting = valid.reduce((m, p) => (p.rs < m.rs ? p : m));
  const closest = pairs.length ? pairs.reduce((m, p) => (p.gap < m.gap ? p : m)) : null;
  return { basis, pairs, complete: pairs.length > 0 && !missing.length, missing,
    minRs: limiting ? limiting.rs : null, limiting,
    lowestKnown: valid.length ? valid.reduce((m, p) => (p.rs < m.rs ? p : m)) : null,
    closest, closestIsLimiting: !!(limiting && closest && limiting.from === closest.from) };
}

// α = K(later) / K(earlier) for a retained pair (SELECTIVITY Discovery Book §2.2).
export function selectivityFactor(k1, k2) {
  const a = positive(k1), b = positive(k2);
  if (a === null || b === null) return { ok: false, reason: 'Both K values must be positive.' };
  return { ok: true, alpha: b / a };
}

// ---------------------------------------------------------------- t0 estimate
// Equipment LAB deck slide 48: column volume = π r² L × 0.68 / 1000 (mL), the
// 0.68 factor being the mobile-phase (interstitial) fraction given in that deck.
// t0 = volume / flow (RETENTION Discovery Book §5.2).
export const T0_ESTIMATE_FACTOR = 0.68;
export function columnVolumeT0(lengthMm, idMm, flowMlMin, factor = T0_ESTIMATE_FACTOR) {
  const L = positive(lengthMm), d = positive(idMm), F = positive(flowMlMin);
  const missing = [];
  if (L === null) missing.push('column length'); if (d === null) missing.push('internal diameter'); if (F === null) missing.push('flow rate');
  if (missing.length) return { ok: false, reason: `Cannot estimate t0: ${missing.join(', ')} not known.` };
  const vol = Math.PI * (d / 2) ** 2 * L * factor / 1000;
  return { ok: true, t0: vol / F, volume: vol, formula: `π × (${d}/2)² × ${L} × ${factor} / 1000 = ${vol.toFixed(3)} mL; t0 = ${vol.toFixed(3)} / ${F} = ${(vol / F).toFixed(3)} min` };
}

// ---------------------------------------------------------------- temperature rule of thumb
// SELECTIVITY Discovery Book §2.6 and Selectivity ED slides 27–28: tR falls by
// about 1–2 % per 1 °C rise. Reported only as a bracket.
export function temperatureBracket(tR, fromC, toC) {
  const t = positive(tR), a = num(fromC), b = num(toC);
  if (t === null) return { ok: false, reason: 'No measured retention time to scale.' };
  if (a === null) return { ok: false, reason: 'The current column temperature is not known, so no temperature prediction is made. (An unknown temperature is not assumed to be 20 or 25 °C.)' };
  if (b === null) return { ok: false, reason: 'No target temperature.' };
  const dT = b - a, hi = t * (1 - 0.01 * dT), lo = t * (1 - 0.02 * dT);
  if (!(hi > 0 && lo > 0)) return { ok: false, reason: `ΔT ${dT} °C takes the rule of thumb outside its meaningful range.` };
  return { ok: true, dT, min: Math.min(hi, lo), max: Math.max(hi, lo) };
}

// ---------------------------------------------------------------- pressure scaling
// Darcy's law for a packed bed: ΔP ∝ u·η·L/dp² with linear velocity u ∝ F/ID².
// At unchanged mobile phase, temperature and packing:
//   ΔP2/ΔP1 = (F2/F1)(L2/L1)(dp1/dp2)²(ID1/ID2)².
// (v13 used (ID1/ID2)⁴, the open-tube form; corrected in v14.)
// An estimate from one measured point — never clearance to inject.
export function pressureScale(measuredPsi, from, to) {
  const P = positive(measuredPsi);
  if (P === null) return { ok: false, reason: 'No measured back-pressure to scale from.' };
  const names = { flow: 'flow rate', length: 'column length', dp: 'particle size', id: 'internal diameter' };
  for (const k of Object.keys(names)) if (positive(from[k]) === null || positive(to[k]) === null)
    return { ok: false, reason: `Cannot scale: ${names[k]} not known for both the measured and the proposed run.` };
  const est = P * (to.flow / from.flow) * (to.length / from.length) * (from.dp / to.dp) ** 2 * (from.id / to.id) ** 2;
  return { ok: true, estimate: est,
    formula: `${P.toFixed(0)} × (${to.flow}/${from.flow}) × (${to.length}/${from.length}) × (${from.dp}/${to.dp})² × (${from.id}/${to.id})² = ${est.toFixed(0)} psi` };
}

// ---------------------------------------------------------------- formatting
export function fmt(v, dp = 3) { const n = num(v); return n === null ? '—' : n.toFixed(dp); }

// alpha.mjs — selectivity α = K(later) / K(earlier) for adjacent retained
// peaks of one run (SELECTIVITY Discovery Book §2.2). Not calculated without
// an established t0. Pairs are by elution position in that run; no compound
// identity is implied.
import { retentionFactor, selectivityFactor } from '../rules.mjs';
import { t0Of, relevantPeaks } from '../data-model/derive.mjs';

export function alphaPairs(session, run, settings) {
  const t0 = t0Of(session, run, settings);
  if (!t0.ok) return { ok: false, reason: `α not calculated: ${t0.text}` };
  const retained = relevantPeaks(run).filter(p => p.tR > t0.t0 + 1e-9).map(p => ({ ...p, K: retentionFactor(p.tR, t0.t0) })).filter(p => p.K.ok);
  const pairs = [];
  for (let i = 1; i < retained.length; i++) {
    const a = retained[i - 1], b = retained[i]; const al = selectivityFactor(a.K.k, b.K.k);
    pairs.push({ from: a.no, to: b.no, k1: a.K.k, k2: b.K.k, alpha: al.ok ? al.alpha : null });
  }
  return { ok: true, t0, pairs, note: 'Adjacent retained peaks in elution order of this run. α measures spacing of apices only; it ignores width (unlike Rs). Positions are not identities.' };
}

// completion.mjs — when does a historical run COMPLETE a selectivity step?
//
// A selectivity step is an experiment: "run the same sample, on the same
// column, in this solvent, at this temperature, at the composition under
// development, and look at what happened to the spacing." A run is evidence
// that the step was done only if it actually was that experiment and if it can
// be read. Matching the column, the solvent and the temperature is not enough:
// a run at another composition answers a different question, a run on another
// sample answers it for another sample, and a run that breached the
// back-pressure specification is not a method anyone may repeat.
//
// Five verdicts are kept apart, because they lead to different actions:
//   'completed'     — performed, valid and evaluable: the step is done.
//   'invalid'       — performed, but it cannot stand as evidence for THIS step
//                     (wrong composition, another sample, a breached limit…).
//   'inconclusive'  — performed and admissible, but it cannot be read
//                     (no peaks, no resolution under the selected basis,
//                     unknown temperature…).
//   'not-this-step' — a run that simply belongs to another step.
//   (a step itself can also be 'unavailable'; that is decided in progression.)
//
// Nothing here guesses. Where a quantity is unknown, the verdict says so
// instead of assuming the quantity matches.
import { runColumn, organicOf, percentBOf, effectiveTemperature, modeOf, relevantPeaks, isBlank, flowOf } from '../data-model/derive.mjs';
import { usable, knownValue } from '../data-model/conditions.mjs';
import { compare, OPERATORS, adjacentResolutions } from '../rules.mjs';
import { sampleCompare } from '../data-model/comparability.mjs';

export const VERDICT = {
  COMPLETED: 'completed',
  INVALID: 'invalid',
  INCONCLUSIVE: 'inconclusive',
  OTHER_STEP: 'not-this-step',
};

// What may differ between the run and the current conditions without changing
// the question the step asks, and what may not. Stated here so the contract is
// readable in one place rather than implied by a chain of conditions.
export const COMPLETION_CONTRACT = {
  id: 'rule.stepCompletion',
  label: 'What makes a historical run evidence that a selectivity step was completed',
  mustMatch: [
    'the explicitly declared sample/study ID or a recorded user equivalence: sample type/name alone cannot establish identity',
    'the physical column, confirmed, with its stationary phase recorded (the ligand step is the exception: it needs a different, recorded ligand)',
    'the organic solvent of the step, confirmed',
    'the composition under development: the step changes temperature or solvent, NOT %B, so the run must be at the current %B — or, for a solvent step, at the nomogram-converted composition within the stated reading allowance',
    'the mobile phase otherwise: pH, additive, additive concentration and phase A where both runs record them',
    'isocratic elution: the step is defined at a fixed composition',
    'the temperature of the step, known and stable within the configured tolerance',
  ],
  mayDiffer: [
    'flow rate — K is unchanged by flow at constant chemistry, and each run carries its own t0',
    'injection volume, sample concentration and detection wavelength — they do not change the separation (they are noted, not counted against the run)',
    'acquisition time, provided the latest peak is inside it',
  ],
  invalidating: [
    'a measured back-pressure that does not meet the configured specification: the run happened, but it is not a method that may be repeated, so it is not evidence that a safe, evaluable step was completed',
    'a different declared sample identity without an equivalence, a different composition, a different mobile phase, a gradient, or an unconfirmed or different column',
  ],
  evaluable: 'A step about selectivity can only be read from a run with at least two relevant peaks and a lowest adjacent-pair resolution calculable under the selected basis. Otherwise the run is INCONCLUSIVE: performed, admissible, but silent on the question.',
  note: 'Tool contract, assembled from the course material (comparability in RETENTION Discovery Book §6 and §8.2, selectivity in SELECTIVITY Discovery Book §2.2–2.7, the back-pressure cut-off in Equipment LAB slides 35–36) and from the FC1 rubric\'s requirement that the history be read. The rubric does not itself list these conditions.',
};

const opl = op => OPERATORS[op]?.label || op;

// Is the composition of `run` the one the step is asked at?
// For a step on the base solvent that is the current run's own %B. For a step
// that changes solvent it is the nomogram-converted composition, within the
// stated reading allowance of the digitised figure.
// A step is a COMPARISON, so it needs its control at the same composition: a
// temperature step is read against the same sample at the same composition in
// the same solvent at the base temperature, and a solvent step is read against
// the base-solvent condition it was converted from. `ctx.targets` carries the
// admissible compositions with the run each one comes from, built by
// `compositionTargets()` below. Nothing is anchored to the run being judged, so
// a run can never justify itself.
function compositionCheck(run, step, targets) {
  const b = percentBOf(run);
  if (b === null) return { ok: false, hard: true, text: 'its %B is not confirmed, so the composition it was run at is unknown' };
  if (!targets || targets.kind === 'unestablished')
    return { ok: false, hard: false, text: `the composition this step belongs to is not established: ${targets?.reason || 'no comparable condition is recorded'}` };
  if (targets.kind === 'any') return { ok: true, text: `${b} %B (this step does not fix a composition: ${targets.reason})` };
  const hit = targets.list.find(t => Math.abs(b - t.B) <= (t.tolerance ?? 0) + 1e-9);
  if (hit) return { ok: true, text: `${b} %B matches ${hit.B} %B${hit.tolerance ? ` ± ${hit.tolerance}` : ''} — ${hit.basis}`, control: hit };
  const near = [...targets.list].sort((x, y) => Math.abs(b - x.B) - Math.abs(b - y.B)).slice(0, 2);
  return { ok: false, hard: true,
    text: `it was run at ${b} %B, and this step belongs to ${targets.list.length === 1 ? 'the composition' : 'one of the compositions'} ${near.map(t => `${t.B} %B${t.tolerance ? ` ± ${t.tolerance}` : ''} (${t.basis})`).join(' or ')}${targets.list.length > 2 ? `, among ${targets.list.length} admissible compositions` : ''}; a selectivity step changes temperature or solvent, not the composition, so a run at another composition answers a different question and cannot complete this step` };
}

// Which compositions does this step belong to, and on what evidence?
//   * a step with a temperature target → the compositions at which a
//     base-temperature run on the SAME column, solvent and sample exists; that
//     run is the control the step is read against;
//   * a step that moves to the second solvent at the base temperature → the
//     nomogram conversions of those base-solvent control compositions, with
//     the figure's stated reading allowance;
//   * a step with a temperature target on the second solvent → the
//     compositions of its own base-temperature runs on that solvent, falling
//     back to the conversions when the solvent step itself has not been run.
// With nothing to compare against, the result is 'unestablished' and runs are
// neither counted nor rejected on composition.
export function compositionTargets(session, settings, current, step, ctx) {
  const onColumn = (ctx.history || []).filter(r => {
    const col = runColumn(session, r);
    if (!col.confirmed || col.column?.id !== ctx.columnId) return false;
    if (percentBOf(r) === null) return false;
    return sampleCompare(session, r, current).comparable;
  });
  const baseTempRunsIn = solvent => onColumn.filter(r => organicOf(r) === solvent && (ctx.baseTemperature ? ctx.baseTemperature(r).ok : true));
  const dedupe = list => { const seen = new Map(); for (const t of list) if (!seen.has(t.B)) seen.set(t.B, t); return [...seen.values()].sort((a, b) => a.B - b.B); };

  const stepSolvent = step.solventName;
  const base = ctx.baseSolvent;
  const hasTemperature = step.temperature !== null && step.temperature !== undefined;

  if (hasTemperature) {
    const own = baseTempRunsIn(stepSolvent);
    if (own.length) return { kind: 'list', list: dedupe(own.map(r => ({ B: percentBOf(r), tolerance: 0, basis: `the base-temperature control run "${r.label}" at that composition in ${stepSolvent}`, controlRunId: r.id }))) };
    if (stepSolvent !== base) {
      const conv = convertedTargets(baseTempRunsIn(base), base, stepSolvent, ctx);
      if (conv.length) return { kind: 'list', list: dedupe(conv), note: `no base-temperature run in ${stepSolvent} exists yet, so the admissible compositions are the nomogram conversions of the ${base} conditions` };
    }
    return { kind: 'unestablished', reason: `no run on this column in ${stepSolvent} at the base temperature carries a confirmed %B, so this temperature step has no control to be read against` };
  }
  // base temperature on the second solvent: the converted base-solvent conditions
  if (stepSolvent && stepSolvent !== base) {
    const conv = convertedTargets(baseTempRunsIn(base), base, stepSolvent, ctx);
    if (conv.length) return { kind: 'list', list: dedupe(conv) };
    return { kind: 'unestablished', reason: `no ${base} condition on this column can be converted to ${stepSolvent}: ${ctx.conversionReason || 'the nomogram gives no reading for it'}` };
  }
  return { kind: 'any', reason: 'it is the base condition of the base solvent, which the retention series itself establishes' };
}

function convertedTargets(baseRuns, base, to, ctx) {
  const out = [];
  for (const r of baseRuns) {
    const b = percentBOf(r);
    const cv = ctx.convert(base, to, b);
    if (cv?.available) out.push({ B: cv.rounded, tolerance: ctx.nomogramTolerance ?? 2, basis: `the nomogram conversion of ${b} %B ${base} (run "${r.label}") into ${to}`, controlRunId: r.id, fromB: b });
  }
  return out;
}

// Can this run be read for a selectivity question at all?
function evaluability(session, settings, run) {
  const peaks = relevantPeaks(run);
  if (peaks.length < 2) return { ok: false, text: `it reports ${peaks.length} relevant peak(s): a spacing question needs at least two` };
  const rs = adjacentResolutions(peaks, settings.rsBasis);
  if (!rs || !rs.complete) {
    const missing = rs?.missing?.length ? rs.missing.map(m => `${m.from}–${m.to}: ${m.reason}`).join('; ') : 'no adjacent pair could be calculated';
    return { ok: false, text: `its lowest adjacent-pair resolution cannot be calculated on the ${settings.rsBasis} basis (${missing}), so the step cannot be read from it` };
  }
  return { ok: true, text: `${peaks.length} relevant peaks and a lowest adjacent Rs of ${rs.minRs.toFixed(3)} on the ${settings.rsBasis} basis` };
}

// The one call progression makes, per historical run and per step.
export function classifyRun(session, settings, current, step, run, ctx = {}) {
  const reasons = [], notes = [];
  const push = (v, text) => ({ verdict: v, reasons: [...reasons, text], notes });

  // 0. does it even belong to this step?
  const col = runColumn(session, run);
  const stepSolvent = step.solventName || null;
  if (isBlank(run)) return push(VERDICT.OTHER_STEP, 'it is recorded as a blank, so it carries no analyte information');
  if (!col.column) return push(VERDICT.INVALID, 'no physical column is associated with it');
  if (!col.confirmed) return push(VERDICT.INVALID, `its column association ("${col.column.label}") is not confirmed`);
  if (col.column.id !== ctx.columnId) return push(VERDICT.INVALID, `it was run on a different physical column ("${col.column.label}")`);
  const org = organicOf(run);
  if (stepSolvent && org !== stepSolvent) return push(VERDICT.OTHER_STEP, `its organic solvent is ${org || 'not recorded'}, not ${stepSolvent}`);

  // 1. the sample the step is about
  const sample = sampleCompare(session, run, current);
  if (!sample.comparable) return push(sample.identities.every(x => x.known) ? VERDICT.INVALID : VERDICT.INCONCLUSIVE, sample.reasons.join('; '));
  notes.push(...sample.notes);

  // 2. the stationary phase has to be recorded for the step to mean anything
  if (!col.model?.ligand) notes.push('the stationary phase of this column model is not recorded; the step is still counted on the identity of the physical column, but the phase cannot be stated');

  // 3. isocratic
  const mode = modeOf(run);
  if (mode && mode !== 'ISO') return push(VERDICT.INVALID, `it is ${mode}: a selectivity step is defined at a fixed composition`);

  // 5. the rest of the mobile phase
  for (const [k, label] of [['pH', 'pH'], ['additiveName', 'additive'], ['additiveConc', 'additive concentration'], ['phaseA', 'phase A']]) {
    const a = run.conditions[k], b = current.conditions[k];
    if (usable(a) && usable(b) && String(a.value) !== String(b.value)) return push(VERDICT.INVALID, `its ${label} (${a.value}) differs from the current run's (${b.value})`);
  }

  // 5. the temperature of the step
  const T = effectiveTemperature(run, settings);
  if (step.temperature !== null && step.temperature !== undefined) {
    if (!T.known) return push(VERDICT.INCONCLUSIVE, `its column temperature is not established: ${T.reason}`);
    if (Math.abs(T.value - step.temperature) > settings.tempStabilityTolerance)
      return push(VERDICT.OTHER_STEP, `it ran at ${T.value.toFixed(1)} °C, not at the ${step.temperature} °C of this step`);
    notes.push(`temperature ${T.value.toFixed(1)} °C within ${settings.tempStabilityTolerance} °C of the ${step.temperature} °C step (${T.reason})`);
  } else if (ctx.baseTemperature) {
    const b = ctx.baseTemperature(run);
    if (!b.ok) return push(b.known === false ? VERDICT.INCONCLUSIVE : VERDICT.OTHER_STEP, b.why);
    notes.push(b.why);
  }

  // 6. the composition this step belongs to (checked after the temperature, so a
  //    base-temperature control run is simply another step, not a rejection)
  const comp = compositionCheck(run, step, ctx.targets);
  if (!comp.ok) return push(comp.hard ? VERDICT.INVALID : VERDICT.INCONCLUSIVE, comp.text);
  notes.push(comp.text);
  if (comp.control?.controlRunId === run.id) return push(VERDICT.INVALID, 'it is itself the control this step would be read against, so it cannot also be the step');

  // 7. method constraints: a run that breached the pressure specification is
  //    not a method that may be repeated, so it is not evidence of a safe step
  const P = run.measured?.pressure?.max;
  const spec = settings.specs?.pressure;
  if (spec && Number.isFinite(P)) {
    const c = compare(P, spec.op, spec.value);
    if (c.known && !c.pass) {
      const r = push(VERDICT.INVALID, `its measured back-pressure ${P.toFixed(0)} psi does not meet the configured ${opl(spec.op)} ${spec.value} psi specification: the run happened, but it is not a method that may be repeated, so it is not evidence that a safe, evaluable step was completed`);
      r.unsafePressure = { label: run.label, pressurePsi: P, flow: flowOf(run) };
      return r;
    }
    notes.push(`measured back-pressure ${P.toFixed(0)} psi meets ${opl(spec.op)} ${spec.value} psi`);
  } else if (spec) {
    reasons.push('its back-pressure is not recorded, so it cannot be shown to have been within the specification');
  }

  // 8. can the step be read from it?
  const ev = evaluability(session, settings, run);
  if (!ev.ok) return push(VERDICT.INCONCLUSIVE, ev.text);
  notes.push(ev.text);

  // anything still in `reasons` is a fact that could not be established
  if (reasons.length) return { verdict: VERDICT.INCONCLUSIVE, reasons, notes };
  return { verdict: VERDICT.COMPLETED, reasons: ['the sample, column, solvent, composition, mobile phase, temperature and pressure all match the step, and the run can be read'], notes };
}

// gates.mjs — evaluate ONE run against the configured specifications, in the
// sourced decision order: pressure/operating constraints → peak count →
// last relevant peak → lowest adjacent-pair resolution.
import { compare, adjacentResolutions, RS_BASES, OPERATORS, toPsi } from '../rules.mjs';
import { relevantPeaks, runColumn, runInstrument, effectiveTemperature, flowOf } from '../data-model/derive.mjs';
import { columnLimit } from '../data-model/equipment.mjs';
import { peakStatus } from '../alignment/correspondence.mjs';
import { usable } from '../data-model/conditions.mjs';
import { labPressureSettings } from '../presets/local-lab.mjs';

const opText = op => OPERATORS[op]?.label || op;

export function evaluateRun(session, run, settings) {
  const S = labPressureSettings(session, settings, run).specs;
  const peaks = relevantPeaks(run);
