  const lowPx=Math.max(F[0],T[0]),highPx=Math.min(F[F.length-1],T[T.length-1]);
  if(!(highPx>lowPx))return {low:null,high:null,empty:true};
  return {low:interp(F,NOMOGRAM_DECADES,lowPx),high:interp(F,NOMOGRAM_DECADES,highPx),
    lowPx,highPx,empty:false};
}

export const NOMOGRAM_SOLVENTS=Object.keys(NOMOGRAM_AXES);

// Returns the isoeluotropic composition of `to` matching `percent` of `from`.
// Never invents a number: an unsupported solvent, a missing %B or a value
// outside the axis range returns available:false with what must be confirmed.
export function nomogramConvert(from,to,percent){
  const base={from,to,input:percent,available:false,value:null,rounded:null,
    tolerance:NOMOGRAM_TOLERANCE,toleranceBasis:NOMOGRAM_TOLERANCE_BASIS,
    approximation:null,attribution:NOMOGRAM_ATTRIBUTION,
    approximationNote:NOMOGRAM_APPROXIMATION_NOTE,readableRange:null,reason:''};
  if(!NOMOGRAM_AXES[from]||!NOMOGRAM_AXES[to])
    return {...base,reason:`CANNOT BE CONVERTED — confirm. The supplied nomogram carries ${Object.keys(NOMOGRAM_AXES).join(', ')} against water only. ${!NOMOGRAM_AXES[from]?`"${from}"`:`"${to}"`} is not on it.`};
  // Number(null) and Number('') are 0, which is a finite number but not a
  // recorded composition. An unrecorded %B must never read as 0 %B.
  if(percent===null||percent===undefined||percent==='')
    return {...base,reason:'CANNOT BE CONVERTED — confirm the current %B. It is not recorded on this run, so there is nothing to read across the nomogram.'};
  const p=Number(percent);
  if(!Number.isFinite(p))
    return {...base,reason:'CANNOT BE CONVERTED — confirm the current %B. The recorded value is not a number, so there is nothing to read across the nomogram.'};
  if(p<0||p>100)
    return {...base,reason:`CANNOT BE CONVERTED — confirm. ${p}%B lies outside the 0–100 % range the supplied nomogram covers.`};
  const range=nomogramReadableRange(from,to);
  if(from===to)return {...base,available:true,value:p,rounded:Math.round(p),approximation:p,
    readableRange:range,reason:'Same solvent: no conversion needed.'};
  const xFrom=interp(NOMOGRAM_DECADES,NOMOGRAM_AXES[from],p);
  if(xFrom===null)
    return {...base,readableRange:range,
      reason:`CANNOT BE CONVERTED — ${p}% ${from} is outside the span of the ${from} axis as digitised.`};
  // v13 CORRECTION: validate the COMMON range before reading across. The two
  // axes are not drawn to the same length, so a coordinate can sit on one axis
  // and beyond the end of the other. v12 clamped and returned a fabricated
  // endpoint; this refuses and says why.
  const value=interp(NOMOGRAM_AXES[to],NOMOGRAM_DECADES,xFrom);
  if(value===null||!Number.isFinite(value))
    return {...base,readableRange:range,
      reason:`CANNOT BE CONVERTED — ${p}% ${from} falls beyond the end of the ${to} axis on the supplied figure, so the figure carries no ${to} equivalent for it. The two axes are not drawn to the same length. On this figure the readable range is ${range&&range.low!==null?`${range.low.toFixed(1)}–${range.high.toFixed(1)}% ${from}`:'empty'}. No value is issued; confirm the composition another way.`};
  let approximation=null;
  if(from==='ACN'&&to==='MeOH')approximation=p*60/50;
  else if(from==='MeOH'&&to==='ACN')approximation=p*50/60;
  const rounded=Math.round(value);
  const approxRounded=approximation===null?null:Math.round(approximation*10)/10;
  const approxNote=approxRounded===null?''
    :approxRounded>100||approxRounded<0
      ? ` The course’s ratio approximation gives ${approxRounded.toFixed(1)}%, which is not a possible composition: the approximation is anchored on the single pair 50 % ACN / 60 % MeOH and does not hold here. The nomogram reading is the value to use.`
      : ` The course’s ratio approximation gives ${approxRounded.toFixed(1)}%, recorded as the cross-check the notebook procedure asks for (p. 27/70). Where the two differ, the nomogram reading is the planned composition.`;
  return {...base,available:true,value,rounded,approximation:approxRounded,
    approximationUsable:approxRounded===null?null:(approxRounded>=0&&approxRounded<=100),
    readableRange:range,
    reason:`Read across the supplied nomogram: ${p}% ${from} is isoeluotropic with ${value.toFixed(1)}% ${to} (plan ${rounded}% ${to}, chosen reading allowance ±${NOMOGRAM_TOLERANCE} percentage points).${approxNote}`};
}


export const NOMOGRAM_LIMIT=
  'The nomogram matches ELUTION STRENGTH, not selectivity. That is the point of the change: matching the strength is what makes the two chromatograms comparable, so any change in peak spacing can be attributed to solvent chemistry rather than to strength. Individual compounds shift by different amounts, so peak spacing, the identity of the critical pair and the ELUTION ORDER may all change. Any retention time predicted at the converted composition is a starting estimate and must be confirmed by injection.';

// progression.mjs — history-aware selectivity progression.
//
// A step counts as DONE only when an actual run in the decision-history set
// shows it: same confirmed physical column (or, for the ligand step, a
// different column whose ligand differs), the step's organic solvent
// (confirmed), and a KNOWN temperature that matches the step. A run with an
// unknown or unstable temperature, an unconfirmed column, or a different column
// never completes a temperature or solvent step. A recommendation is never
// evidence that a step was done.
import { chronological } from '../data-model/session.mjs';
import { runColumn, organicOf, isBlank, effectiveTemperature, percentBOf } from '../data-model/derive.mjs';
import { columnLimit } from '../data-model/equipment.mjs';
import { knownValue } from '../data-model/conditions.mjs';
import { nomogramConvert, NOMOGRAM_TOLERANCE } from './nomogram.mjs';
import { classifyRun, compositionTargets, VERDICT, COMPLETION_CONTRACT } from './completion.mjs';
import { sampleCompare } from '../data-model/comparability.mjs';

export function historyRuns(session) {
  return chronological(session, session.runs.filter(r => r.flags.history && !isBlank(r) && r.measured.peaks.length));
}

function atBaseTemperature(run, settings) {
  const sp = run.conditions.ovenSetpoint;
  if (knownValue(sp) && sp.value === 'ambient' && sp.confirmed) {
    const T = effectiveTemperature(run, settings);
    if (T.stable === false) return { ok: false, why: T.reason };
    return { ok: true, why: `confirmed "no setpoint (ambient)"${T.known ? `; oven sensor ${T.value.toFixed(1)} °C` : ''}` };
  }
  const T = effectiveTemperature(run, settings);
  const lowest = Math.min(...settings.temperatureSteps);
  if (T.known && T.value < lowest - settings.tempMatchTolerance) return { ok: true, why: `known temperature ${T.value.toFixed(1)} °C, below the first temperature step` };
  return { ok: false, why: T.known ? `temperature ${T.value.toFixed(1)} °C is not the base condition` : T.reason };
}

export function selectivityProgression(session, settings, current) {
  const res = { ok: false, steps: [], next: null, exhausted: false, missing: [], notes: [], base: null };
  if (!current) { res.missing.push('No run in the decision history.'); return res; }
  const cur = runColumn(session, current);
  if (!cur.column || !cur.confirmed) { res.missing.push(`The current run "${current.label}" has no confirmed physical column, so selectivity history on that column cannot be read.`); return res; }
  const hist = historyRuns(session);
  const sameCol = hist.filter(r => { const c = runColumn(session, r); return c.confirmed && c.column?.id === cur.column.id; });
  // base solvent: the solvent of the earliest confirmed run on this column
  const firstKnown = sameCol.find(r => organicOf(r) && sampleCompare(session, r, current).comparable);
  const baseSolvent = settings.baseSolvent || (firstKnown ? organicOf(firstKnown) : organicOf(current));
  if (!baseSolvent) { res.missing.push('The organic solvent of the retention runs on this column is not confirmed.'); return res; }
  const alt = settings.availableSolvents.find(s => s !== baseSolvent) || null;
  res.base = { column: cur.column.label, solvent: baseSolvent, solventBasis: settings.baseSolvent ? 'settings' : firstKnown ? `earliest confirmed run on this column with a comparable declared sample ("${firstKnown.label}")` : `current run's recorded solvent; no same-sample historical base is established`, alt };
  const [T1, T2] = settings.temperatureSteps;
  const tFor = key => key === 'T1' ? T1 : key === 'T2' ? T2 : null;
  const tol = settings.tempStabilityTolerance;
  const colT = columnLimit(cur.model, 'temperature');
  const unavailable = new Set(settings.unavailableSteps || []);

  for (const step of settings.selectivityPlan) {
    const st = { ...step, done: false, evidence: [], rejected: [], classified: [], priorUnsafe: [], performed: 0, available: true, limitsUnverified: false, needs: [] };
    if (unavailable.has(step.id)) { st.available = false; st.unavailableReason = 'Marked by the user as not available.'; res.steps.push(st); continue; }
    if (step.kind === 'ligand') {
      const curLig = cur.model?.ligand || null;
      if (!curLig) st.needs.push('the ligand of the current column model is not recorded');
      const others = session.columns.filter(c => c.id !== cur.column.id).map(c => ({ c, m: session.columnModels.find(m => m.id === c.modelId) }))
        .filter(x => x.m?.ligand && curLig && x.m.ligand !== curLig);
      st.alternatives = others.map(x => `${x.c.label} (${x.m.ligand})`);
      for (const r of hist) {
        const c = runColumn(session, r);
        if (!c.confirmed || !c.column || c.column.id === cur.column.id) continue;
        const sample = sampleCompare(session, r, current);
        if (!sample.comparable) {
          const why = sample.reasons.join('; ');
          st.rejected.push(`${r.label}: ${why}`);
          st.classified.push({ runId: r.id, label: r.label, verdict: sample.identities.every(x => x.known) ? VERDICT.INVALID : VERDICT.INCONCLUSIVE, reasons: sample.reasons, notes: sample.notes });
          continue;
        }
        if (c.model?.ligand && curLig && c.model.ligand !== curLig) { st.evidence.push(r.label); st.classified.push({ runId: r.id, label: r.label, verdict: VERDICT.COMPLETED, reasons: [`run on "${c.column.label}", whose ligand (${c.model.ligand}) differs from the current column's (${curLig})`], notes: [] }); }
        else { const why = `different column but ligand ${c.model?.ligand ? 'the same' : 'not recorded'}`; st.rejected.push(`${r.label}: ${why}`); st.classified.push({ runId: r.id, label: r.label, verdict: VERDICT.INVALID, reasons: [why], notes: [] }); }
      }
      st.done = st.evidence.length > 0;
      st.performed = st.classified.length;
      if (!st.done && !others.length) { st.available = false; st.unavailableReason = 'No alternative column with a different, recorded ligand is in the equipment library. Record one, or mark this step as not available.'; }
      res.steps.push(st); continue;
    }
    const solvent = step.solvent === 'base' ? baseSolvent : alt;
    if (!solvent) { st.available = false; st.unavailableReason = 'No second organic solvent is listed as available.'; res.steps.push(st); continue; }
    st.solventName = solvent;
    const target = tFor(step.temp);
    if (target !== null) {
      st.temperature = target;
      if (!colT.known) { st.limitsUnverified = true; st.needs.push(colT.reason); }
      else if (target > colT.value) { st.available = false; st.unavailableReason = `${target} °C exceeds the documented maximum ${colT.value} °C of ${cur.model.product}.`; }
    }
    // Every historical run is classified against the step-completion contract
    // (src/selectivity/completion.mjs). Matching the column, the solvent and
    // the temperature is NOT sufficient: the sample, the composition under
    // development, the rest of the mobile phase, the pressure specification
    // and whether the run can be read at all all decide the verdict, and the
    // verdict for every run is kept with its reasons.
    const ctx = {
      columnId: cur.column.id,
      history: hist,
      conversion: (solvent && solvent !== organicOf(current)) ? nomogramConvert(organicOf(current), solvent, percentBOf(current)) : null,
      nomogramTolerance: NOMOGRAM_TOLERANCE,
      baseTemperature: r => { const b = atBaseTemperature(r, settings); return { ...b, known: effectiveTemperature(r, settings).known }; },
    };
    ctx.baseSolvent = baseSolvent;
    ctx.convert = (from, to, b) => nomogramConvert(from, to, b);
    ctx.conversionReason = ctx.conversion?.reason || null;
    ctx.targets = compositionTargets(session, settings, current, st, ctx);
    st.compositionTargets = ctx.targets;
    for (const r of hist) {
      const c = classifyRun(session, settings, current, st, r, ctx);
      if (c.verdict === VERDICT.OTHER_STEP) continue;   // belongs to another step; not reported here
      st.classified.push({ runId: r.id, label: r.label, verdict: c.verdict, reasons: c.reasons, notes: c.notes });
      if (c.verdict === VERDICT.COMPLETED) st.evidence.push(r.label);
      else st.rejected.push(`${r.label} [${c.verdict}]: ${c.reasons.join('; ')}`);
      if (c.unsafePressure) st.priorUnsafe.push(c.unsafePressure);
    }
    st.performed = st.classified.length;
    st.done = st.evidence.length > 0;
    res.steps.push(st);
  }
  res.next = res.steps.find(s => !s.done && s.available) || null;
  res.exhausted = !res.next && res.steps.every(s => s.done || (!s.available && s.unavailableReason));
  res.ok = true;
  res.contract = COMPLETION_CONTRACT;
  // composition proposed for a solvent change: nomogram from the current run's %B
  if (res.next && res.next.solventName && res.next.solventName !== organicOf(current)) {
    res.next.conversion = nomogramConvert(organicOf(current), res.next.solventName, percentBOf(current));
  }
  return res;
}

import {organicOf,percentBOf,modeOf,isBlank,relevantPeaks,effectiveTemperature} from '../data-model/derive.mjs';
import {nomogramConvert} from './nomogram.mjs';
import {evaluateRun} from './gates.mjs';
import {shortRunLabel} from '../data-model/workspaces.mjs';
import {sha256} from '../data-model/ids.mjs';
// OBSERVE hypotheses, not compound-specific MeOH predictions.
export function acnReferences(s){return s.runs.filter(r=>!isBlank(r)&&modeOf(r)==='ISO'&&organicOf(r)==='ACN'&&Number.isFinite(percentBOf(r))&&relevantPeaks(r).length).map(r=>{
 const p=relevantPeaks(r),basis=p.every(x=>x.widthBase>0)?'base-width':p.every(x=>x.widthHalf>0)?'half-width':p.every(x=>x.plates>0)?'plate-gaussian':s.settings.rsBasis,g=evaluateRun(s,r,{...s.settings,rsBasis:basis}),rs=g.gates.find(x=>x.id==='minRs')?.value??null,t=effectiveTemperature(r,s.settings);
 return {runId:r.id,label:shortRunLabel(r),B:percentBOf(r),peaks:p.length,last:Math.max(...p.map(x=>x.tR)),rs:p.length===s.settings.specs.peakCount.value?rs:null,temperature:t.known?t.value:r.conditions.ovenSetpoint?.value,pressure:g.gates.find(x=>x.id==='pressure'),run:r};
 }).sort((a,b)=>(b.peaks===s.settings.specs.peakCount.value)-(a.peaks===s.settings.specs.peakCount.value)||(b.rs??-1)-(a.rs??-1)||a.last-b.last||a.runId.localeCompare(b.runId));}
export function solventSuggestions(s,sourceId=s.settings.solventPlan?.sourceRunId){
 const references=acnReferences(s),source=sourceId?references.find(x=>x.runId===sourceId):references[0],strip=({run,...x})=>x,out={references:references.map(strip),source:source?strip(source):null,candidates:[],selected:null};
 if(!source)return {...out,reason:sourceId?'Selected ACN reference is no longer eligible; select a current CSV.':'Import an ACN isocratic sample CSV to obtain reference-based MeOH hypotheses.'};
 const conversion=nomogramConvert('ACN','MeOH',source.B);if(!conversion.available)return {...out,conversion,reason:conversion.reason};
 const signature=sha256(JSON.stringify([source.runId,source.run.raw.sha256,source.run.measured,source.run.conditions,source.run.assoc,source.run.peakNotes,source.run.heightFilter,s.settings.specs,s.settings.rsBasis]));
 const centre=conversion.rounded,timeLimit=s.settings.specs.lastPeak.value,values=[...new Set([centre,...[-5,-2,-1,1,2,5].map(d=>centre+d)])].filter(B=>B>=0&&B<=100);
 out.candidates=values.map(B=>({B,fromB:source.B,sourceRunId:source.runId,to:'MeOH',planningOnly:true,signature,
  reason:B===centre?`Matched-strength starting point: ${source.B}% ACN reads ${conversion.value.toFixed(1)}% MeOH on the course nomogram; rounded to ${centre}%.`:B<centre?`Weaker-solvent probe ${centre-B} points below the matched-strength estimate; may lengthen retention. ${source.last>=timeLimit?'ACN is already near/over the time limit: weaker MeOH is especially exploratory.':'Test whether critical peaks spread; do not assume Rs improves.'}`:`Stronger-solvent probe ${B-centre} points above the matched-strength estimate; may shorten retention. Test peak count and critical-pair spacing; no MeOH tR or Rs is predicted.`,
  evidence:`${source.label}: ${source.peaks} peaks, last tR ${source.last.toFixed(3)} min, ${source.rs===null?'Rs not assessable at the target peak count':'ACN worst-pair Rs '+source.rs.toFixed(3)}. Temperature ${Number.isFinite(source.temperature)?source.temperature.toFixed(1)+' °C':source.temperature??'not established'}.`,
  checks:[...(source.pressure?.specificationPass===false||source.pressure?.operatingFailures?.length?['Source run has an operating/pressure failure; correct it before attempting the plan.']:[]),'Keep sample, column, additives and comparison temperature controlled; solvent chemistry may change peak order.','Measure full MeOH pressure trace, peak count, last tR and Rs; nomogram strength does not prove separation.']}));
 const saved=s.settings.solventPlan;out.selected=saved?.sourceRunId===source.runId&&saved?.signature===signature?out.candidates.find(x=>x.B===saved.B):null;
 return {...out,conversion,signature,reason:'Choose a matched-strength start or an explicitly exploratory bracket. These choices are not a calculated MeOH minimum or a guaranteed optimum.'};
}

