  const series = [];
  (r.fits?.results || []).forEach((x, i) => {
    const sty = styleFor(i);
    if (!x.points.length) return;
    series.push({ id: `p${i}`, label: x.compound.name, ...sty, kind: 'points', points: x.points.map(p => [p.x, p.y]) });
